result.content:
/* CLOSING CTA */
.closing-cta {
  position: relative;
  display: flex;
  min-height: 380px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  text-align: center;
  background: radial-gradient(ellipse at center, rgba(195, 239, 131, 0.05), transparent 60%);
}
.closing-cta h2 {
  margin: 14px 0 10px;
  color: #eceee7;
  font-size: 40px;
  font-weight: 550;
  letter-spacing: -1.8px;
}
.closing-cta > p { margin: 0 0 22px; color: #939895; font-size: 13px; }
.footer { min-height: 75px; color: #73787d; font-size: 11px; }

/* AUTH */
.auth-page { min-height: 100vh; background: #0b0d10; }
.back-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
  color: #a4a8ad;
  font-size: 12px;
  font-weight: 550;
  cursor: pointer;
  transition: all 0.25s var(--ease-spring);
  backdrop-filter: blur(8px);
}
.back-link:hover {
  border-color: rgba(195, 239, 131, 0.5);
  background: rgba(195, 239, 131, 0.08);
  color: #ffffff;
  transform: translateX(-3px);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.3), 0 0 15px rgba(195, 239, 131, 0.12);
}
.back-link svg {
  color: var(--lime);
  transition: transform 0.25s var(--ease-spring);
}
.back-link:hover svg {
  transform: translateX(-2px);
}
.kbd-shortcut {
  display: inline-block;
  padding: 1px 6px;
  font-size: 9px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-weight: 600;
  color: #7d8287;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.05);
  letter-spacing: 0.5px;
  transition: all 0.2s;
}
.back-link:hover .kbd-shortcut {
  border-color: rgba(195, 239, 131, 0.35);
  color: var(--lime);
  background: rgba(195, 239, 131, 0.1);
}

.auth-layout {
  display: grid;
  width: min(1050px, calc(100% - 64px));
  min-height: calc(100vh - 76px);
  grid-template-columns: 1fr 0.88fr;
  align-items: center;
  gap: 90px;
  margin: 0 auto;
  padding: 50px 0;
  animation: smoothReveal 0.8s var(--ease-spring) both;
}
.auth-panel {
  padding: 34px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 14px;
  background: linear-gradient(150deg, rgba(22, 26, 30, 0.98), rgba(15, 18, 22, 0.98));
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.4);
}
.google-button {
  display: flex;
  width: 100%;
  height: 44px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.035);
  color: #e5e5e2;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s var(--ease-spring);
}
.google-button:hover {
  border-color: rgba(195, 239, 131, 0.5);
  background: rgba(195, 239, 131, 0.08);
  color: #ffffff;
  transform: translateY(-2px);
}
.input-wrap {
  display: flex;
  height: 42px;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.25);
  transition: border-color 0.25s var(--ease-spring);
}
.input-wrap:focus-within {
  border-color: var(--lime);
  box-shadow: 0 0 15px rgba(195, 239, 131, 0.15);
}
.input-wrap input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #ffffff;
  font-size: 12px;
}

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; gap: 40px; }
  .bento-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
  .flash-card, .quiz-card, .audio-card, .mindmap-card, .planner-card { grid-column: 1; grid-row: auto; min-height: 280px; }
  .auth-layout { grid-template-columns: 1fr; gap: 40px; }
}

