   const [isSubmitting, setIsSubmitting] = useState(false);

   useEffect(() => {
     function handleKeyDown(event: KeyboardEvent) {
       if (event.key === "Escape") {
         onBack();
       }
     }
     window.addEventListener("keydown", handleKeyDown);
     return () => window.removeEventListener("keydown", handleKeyDown);
   }, [onBack]);

   async function handleSubmit(event: FormEvent<HTMLFormElement>) {
     event.preventDefault();
     setMessage("");
     setIsSubmitting(true);

     const formData = new FormData(event.currentTarget);
     const email = String(formData.get("email") ?? "").trim();
     const password = String(formData.get("password") ?? "");

     try {
       const supabase = createClient();

       if (isSignUp) {
         const fullName = String(formData.get("name") ?? "").trim();
         const { data, error } = await supabase.auth.signUp({
           email,
           password,
           options: {
             data: { full_name: fullName },
             emailRedirectTo: `${window.location.origin}/auth/callback?next=/login-success`,
           },
         });

         if (error) {
           setMessage(error.message);
           return;
         }

         if (!data.session) {
           setMessage("Account created. Check your email to confirm your address, then sign in.");
           return;
         }
       } else {
         const { error } = await supabase.auth.signInWithPassword({ email, password });
         if (error) {
           setMessage(error.message);
           return;
         }
       }

       router.replace("/login-success");
       router.refresh();
     } catch (error) {
       setMessage(
         error instanceof Error
           ? error.message
           : "Unable to sign in right now. Please try again.",
       );
     } finally {
       setIsSubmitting(false);
     }
   }

   async function handleGoogleSignIn() {
     setMessage("");
     setIsSubmitting(true);

     try {
       const { data, error } = await createClient().auth.signInWithOAuth({
         provider: "google",
         options: {
           redirectTo: `${window.location.origin}/auth/callback?next=/login-success`,
           skipBrowserRedirect: true,
         },
       });

       if (error) {
         setMessage(error.message);
         setIsSubmitting(false);
         return;
       }

       if (!data.url) {
         setMessage("Supabase did not return a Google sign-in URL. Check provider settings.");
         setIsSubmitting(false);
         return;
       }

       window.location.assign(data.url);
     } catch (error) {
       setMessage(
         error instanceof Error
           ? error.message
           : "Unable to start Google sign-in. Please try again.",
       );
       setIsSubmitting(false);
     }
   }

   return (
     <main className="auth-page">
       <header className="auth-topbar">
         <Brand onClick={onBack} />
         <button
           type="button"
           className="back-link"
           onClick={onBack}
           title="Return to homepage (Esc)"
         >
           <Icon name="arrow-left" size={14} />
           <span>Back to home</span>
           <span className="kbd-shortcut">ESC</span>
         </button>
       </header>
       <div className="auth-layout">
         <section className="auth-aside">
           <span className="eyebrow"><span className="live-dot" /> YOUR SPACE TO FIGURE IT OUT</span>
           <h1 className="text-4xl sm:text-5xl font-medium tracking-tight text-white my-3">
             Big goals.<br />
             <span>One small step.</span><br />
             You&apos;ve got this.
           </h1>
           <p className="text-[#8c9194] text-xs leading-relaxed max-w-sm">
             A little structure, the right tools, and a space that makes learning feel like yours.
           </p>
         </section>

         <section className="auth-panel">
           <div className="max-w-sm mx-auto">
             <div className="mb-5">
               <span className="section-kicker">{isSignUp ? "A FRESH PAGE" : "GOOD TO HAVE YOU HERE"}</span>
               <h2 className="text-2xl font-medium text-white mt-1">
                 {isSignUp ? "Make it yours." : "Welcome back."}
               </h2>
               <p className="text-xs text-[#8c9194]">
                 {isSignUp ? "Your study space is just a few details away." : "Pick up right where you left off."}
               </p>
             </div>

             {/* Standard Google OAuth Button */}
             <button
               type="button"
               className="google-button"
               onClick={handleGoogleSignIn}
               disabled={isSubmitting}
             >
               <Icon name="google" size={18} />
               {isSubmitting ? "Connecting..." : "Continue with Google"}
             </button>

             <div className="flex items-center gap-2.5 my-4 text-[10px] text-[#81878a]">
               <span className="h-[1px] flex-1 bg-[rgba(255,255,255,0.08)]" />
               or with email
               <span className="h-[1px] flex-1 bg-[rgba(255,255,255,0.08)]" />
             </div>

             <form className="flex flex-col gap-3" onSubmit={handleSubmit}>
               {isSignUp && (
                 <label className="text-[10px] text-[#a0a5aa] flex flex-col gap-1.5">
                   Your name
                   <div className="input-wrap">
                     <span className="text-[#81878a]"><Icon name="spark" size={16} /></span>
                     <input type="text" name="name" placeholder="What should we call you?" autoComplete="name" required />
                   </div>
                 </label>
               )}
               <label className="text-[10px] text-[#a0a5aa] flex flex-col gap-1.5">
                 Email address
                 <div className="input-wrap">
                   <span className="text-[#81878a]"><Icon name="mail" size={16} /></span>
                   <input type="email" name="email" placeholder="you@example.com" autoComplete="email" required />
                 </div>
               </label>
               <label className="text-[10px] text-[#a0a5aa] flex flex-col gap-1.5">
                 Password
                 <div className="input-wrap">
                   <span className="text-[#81878a]"><Icon name="lock" size={16} /></span>
                   <input
                     type={showPassword ? "text" : "password"}
                     name="password"
                     placeholder="At least 8 characters"
                     autoComplete={isSignUp ? "new-password" : "current-password"}
                     minLength={8}
                     required
                   />
                   <button
                     className="text-[#81878a]"
                     type="button"
                     aria-label={showPassword ? "Hide password" : "Show password"}
                     onClick={() => setShowPassword((s) => !s)}
                   >
                     <Icon name="eye" size={17} />
                   </button>
                 </div>
               </label>

               {message && <p className="form-message" role="status">{message}</p>}

               <button className="button-primary w-full mt-2 justify-center" type="submit" disabled={isSubmitting}>
                 {isSubmitting ? "Please wait..." : isSignUp ? "Create your free account" : "Get started"} <Icon name="arrow" size={15} />
               </button>
             </form>

             <p className="text-[10px] text-[#81878a] text-center mt-4">
               {isSignUp ? "Already have an account?" : "New to Synapse?"}{" "}
               <button
                 type="button"
                 className="text-[#c3ef83] hover:underline"
                 onClick={() => { setIsSignUp(!isSignUp); setMessage(""); }}
               >
                 {isSignUp ? "Sign in" : "Create a free account"}
               </button>
             </p>
           </div>
         </section>
       </div>
     </main>
   );
 }

 export default function Home() {
   const [showAuth, setShowAuth] = useState(false);
   const [authMessage, setAuthMessage] = useState("");

   useEffect(() => {
     if (new URLSearchParams(window.location.search).has("authError")) {
