"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { isSupabaseConfigured } from "@/lib/supabase/config";
import { createClient } from "@/lib/supabase/client";

export default function LoginSuccessPage() {
  const router = useRouter();
  const [userEmail, setUserEmail] = useState<string>("harsh@student.synapse.app");
  const [userName, setUserName] = useState<string>("Harsh");
  const [providerName, setProviderName] = useState<string>("Google Account");
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    async function loadUser() {
      try {
        if (isSupabaseConfigured()) {
          const supabase = createClient();
          const { data: { user } } = await supabase.auth.getUser();
          if (user) {
            setUserEmail(user.email ?? "harsh@student.synapse.app");
            const metaName = user.user_metadata?.full_name ?? user.user_metadata?.name;
            if (metaName) {
              setUserName(metaName);
            } else if (user.email) {
              setUserName(user.email.split("@")[0]);
            }
            if (user.app_metadata?.provider) {
              setProviderName(
                user.app_metadata.provider === "google"
                  ? "Google Account"
                  : "Email Account"
              );
            }
          }
        }
      } catch (err) {
        console.error("Supabase user load error:", err);
      } finally {
        setIsLoading(false);
      }
    }

    loadUser();
  }, []);

  async function handleSignOut() {
    try {
      if (isSupabaseConfigured()) {
        const supabase = createClient();
        await supabase.auth.signOut();
      }
    } catch (err) {
      console.error("Sign out error:", err);
    }
    router.push("/");
  }

  return (
    <main className="landing min-h-screen">
      {/* Top Navigation Bar - Matches Landing Page */}
      <header className="topbar">
        <Link href="/" className="brand" aria-label="Synapse home">
          <span className="brand-mark">
            <svg
              width={19}
              height={19}
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={1.8}
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-1.9-5.8L4 11l6.1-2.2L12 3Z" />
            </svg>
          </span>
          <span>synapse<span className="brand-period">.</span></span>
        </Link>

        <div className="flex items-center gap-3">
          <div className="social-proof !mt-0 !py-1 !px-3 text-xs">
            <span className="live-dot" />
            <span>{providerName} · <b>Active Session</b></span>
          </div>
          <button
            type="button"
            className="nav-cta"
            onClick={handleSignOut}
          >
            Sign out
          </button>
        </div>
      </header>

      {/* Main Workspace Dashboard Container */}
      <div className="w-[min(1192px,calc(100%-64px))] mx-auto py-12">
        {/* Welcome Banner */}
        <div className="mb-10 animate-entrance">
          <div className="eyebrow mb-2">
            <span className="live-dot" /> VERIFIED STUDENT COCKPIT
          </div>
          <h1 className="text-3xl sm:text-5xl font-medium tracking-tight text-[#f1f0ec] mb-3">
            Welcome to your study space, <span className="text-[#c3ef83]">{userName} ✳</span>
          </h1>
          <p className="text-[#8c9194] text-xs sm:text-sm max-w-xl leading-relaxed">
            Your notes, progressive learn units, and Notion schedule are synced. Pick up where you left off or start a new focus session.
          </p>
        </div>

        {/* User Status Bento Card */}
        <div className="p-6 sm:p-8 rounded-xl border border-[rgba(255,255,255,0.08)] bg-[#111419] mb-8">
          <div className="flex flex-col sm:flex-row items-center sm:items-start gap-5 border-b border-[rgba(255,255,255,0.06)] pb-6 mb-6">
            <div className="w-16 h-16 rounded-xl border border-[rgba(195,239,131,0.4)] bg-[#182216] text-[#c3ef83] flex items-center justify-center text-2xl font-bold shadow-[0_0_20px_rgba(195,239,131,0.15)]">
              {userName.charAt(0).toUpperCase()}
            </div>

            <div className="flex-1 text-center sm:text-left">
              <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2.5 mb-1.5">
                <h2 className="text-xl font-medium text-white">{userName}</h2>
                <span className="text-[10px] px-2.5 py-0.5 rounded-full border border-[rgba(195,239,131,0.3)] bg-[rgba(195,239,131,0.08)] text-[#c3ef83] font-semibold">
                  ✓ Verified Student
                </span>
                <span className="text-[10px] px-2.5 py-0.5 rounded-full border border-[rgba(255,255,255,0.08)] text-[#8c9194]">
                  Free Forever Plan
                </span>
              </div>
              <p className="text-xs font-mono text-[#8c9194] mb-3">{userEmail}</p>
              <div className="inline-flex items-center gap-2 text-xs text-[#d5d8d1] bg-[rgba(255,255,255,0.03)] border border-[rgba(255,255,255,0.06)] px-3 py-1.5 rounded-lg">
                <span className="w-1.5 h-1.5 rounded-full bg-[#c3ef83]" />
                <span>Active Notebook: <b>Cell Biology · Chapter 4 (Krebs & ATP)</b></span>
              </div>
            </div>
          </div>

          {/* Metrics Row */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-center">
            <div className="p-3 rounded-lg border border-[rgba(255,255,255,0.06)] bg-[rgba(255,255,255,0.02)]">
              <span className="text-[9px] text-[#81878a] tracking-wider uppercase block mb-1">Study Streak</span>
              <span className="text-base font-bold text-[#c3ef83]">🔥 7 Days</span>
            </div>
            <div className="p-3 rounded-lg border border-[rgba(255,255,255,0.06)] bg-[rgba(255,255,255,0.02)]">
              <span className="text-[9px] text-[#81878a] tracking-wider uppercase block mb-1">Flashcards Ready</span>
              <span className="text-base font-bold text-white">18 Cards</span>
            </div>
            <div className="p-3 rounded-lg border border-[rgba(255,255,255,0.06)] bg-[rgba(255,255,255,0.02)]">
              <span className="text-[9px] text-[#81878a] tracking-wider uppercase block mb-1">Quiz Accuracy</span>
              <span className="text-base font-bold text-[#c3ef83]">94%</span>
            </div>
            <div className="p-3 rounded-lg border border-[rgba(255,255,255,0.06)] bg-[rgba(255,255,255,0.02)]">
              <span className="text-[9px] text-[#81878a] tracking-wider uppercase block mb-1">Focus Time</span>
              <span className="text-base font-bold text-white">24:18 (Active)</span>
            </div>
          </div>
        </div>

        {/* Study Modules Launchpad */}
        <div className="mb-10">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xs font-bold text-[#c3ef83] uppercase tracking-wider">
              Launch Study Modules
            </h3>
            <span className="text-[11px] text-[#81878a]">All tools free & unlocked</span>
          </div>

          <div className="grid sm:grid-cols-3 gap-4">
            {/* Tile 1: Turbo Learn Mode */}
            <Link
              href="/#learn-mode"
              className="p-5 rounded-xl border border-[rgba(255,255,255,0.08)] bg-[#111419] hover:border-[rgba(195,239,131,0.4)] transition group block"
            >
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-bold text-[#c3ef83] tracking-wider">01 / LEARN MODE</span>
                <span className="text-[#81878a] group-hover:text-[#c3ef83] transition">→</span>
              </div>
              <h4 className="text-sm font-medium text-white mb-1.5 group-hover:text-[#c3ef83] transition">
                Turbo Learn Units
              </h4>
              <p className="text-[11px] text-[#8c9194] leading-relaxed">
                Step-by-step unit breakdown with verbal explanations & micro-checkpoints.
              </p>
            </Link>

            {/* Tile 2: 3D Flashcards */}
            <Link
              href="/#workspace"
              className="p-5 rounded-xl border border-[rgba(255,255,255,0.08)] bg-[#111419] hover:border-[rgba(195,239,131,0.4)] transition group block"
            >
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-bold text-[#c3ef83] tracking-wider">02 / RECALL</span>
                <span className="text-[#81878a] group-hover:text-[#c3ef83] transition">→</span>
              </div>
              <h4 className="text-sm font-medium text-white mb-1.5 group-hover:text-[#c3ef83] transition">
                3D Flashcard Deck
              </h4>
              <p className="text-[11px] text-[#8c9194] leading-relaxed">
                Active recall review with 3D flip animations and spaced repetition.
              </p>
            </Link>

            {/* Tile 3: 2-Host StudyCast */}
            <Link
              href="/#workspace"
              className="p-5 rounded-xl border border-[rgba(255,255,255,0.08)] bg-[#111419] hover:border-[rgba(195,239,131,0.4)] transition group block"
            >
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-bold text-[#c3ef83] tracking-wider">03 / AUDIO</span>
                <span className="text-[#81878a] group-hover:text-[#c3ef83] transition">→</span>
              </div>
              <h4 className="text-sm font-medium text-white mb-1.5 group-hover:text-[#c3ef83] transition">
                2-Host Audio StudyCast
              </h4>
              <p className="text-[11px] text-[#8c9194] leading-relaxed">
                NotebookLM-style podcast recap with Alex & Taylor and dancing waveform.
              </p>
            </Link>
          </div>
        </div>

        {/* Return Button */}
        <div className="pt-6 border-t border-[rgba(255,255,255,0.06)] flex items-center justify-between">
          <Link href="/" className="back-link">
            <svg
              width={14}
              height={14}
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={1.8}
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M19 12H5" />
              <path d="m11 18-6-6 6-6" />
            </svg>
            <span>Return to workspace</span>
          </Link>
          <span className="text-[10px] text-[#81878a]">Synapse AI Study Cockpit · Open Source</span>
        </div>
      </div>
