@import "tailwindcss";

:root {
  color-scheme: dark;
  --background: #0b0d10;
  --panel: #111419;
  --panel-soft: #15191f;
  --foreground: #eeefec;
  --muted: #858a91;
  --faint: #5d626a;
  --line: rgba(255, 255, 255, 0.075);
  --lime: #c3ef83;
  --lime-dim: rgba(195, 239, 131, 0.12);
  --lime-glow: rgba(195, 239, 131, 0.28);
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
}

* { box-sizing: border-box; }
html {
  scroll-behavior: smooth;
}
body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--lime); outline-offset: 4px; }
a { color: inherit; text-decoration: none; }

/* ULTRA-REFINED ANIMATIONS & KEYFRAMES */
@keyframes smoothReveal {
  from {
    opacity: 0;
    transform: translateY(28px) scale(0.985);
    filter: blur(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes floatSmooth {
  0%, 100% {
    transform: translateY(0px) rotate(0deg);
  }
  50% {
    transform: translateY(-8px) rotate(0.4deg);
  }
}

@keyframes pulseGlow {
  0%, 100% {
    opacity: 0.1;
    transform: scale(1);
  }
  50% {
    opacity: 0.22;
    transform: scale(1.08);
  }
}

@keyframes waveDance {
  0%, 100% {
    transform: scaleY(0.25);
  }
  50% {
    transform: scaleY(1);
  }
}

@keyframes borderGlowPulse {
  0%, 100% {
    box-shadow: 0 0 15px rgba(195, 239, 131, 0.15);
  }
  50% {
    box-shadow: 0 0 30px rgba(195, 239, 131, 0.35);
  }
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

@keyframes gradientShift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

@keyframes textGlow {
  0%, 100% { text-shadow: 0 0 20px rgba(195, 239, 131, 0.3); }
  50% { text-shadow: 0 0 40px rgba(195, 239, 131, 0.6), 0 0 60px rgba(195, 239, 131, 0.3); }
}

@keyframes slideUpFade {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.9); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes rotateIn {
  from { opacity: 0; transform: rotate(-5deg) scale(0.9); }
  to { opacity: 1; transform: rotate(0) scale(1); }
}

@keyframes floatParticle {
  0%, 100% { transform: translate(0, 0) rotate(0deg); opacity: 0.3; }
  25% { transform: translate(30px, -30px) rotate(90deg); opacity: 0.6; }
  50% { transform: translate(-20px, -60px) rotate(180deg); opacity: 0.4; }
  75% { transform: translate(-40px, -20px) rotate(270deg); opacity: 0.5; }
}

/* Modern Scroll-driven reveal where supported */
@supports (animation-timeline: view()) {
  .scroll-reveal {
    animation: smoothReveal 0.85s var(--ease-spring) both;
    animation-timeline: view();
    animation-range: entry 10% cover 30%;
  }
  .scroll-reveal-delay-1 { animation-delay: 0.1s; }
  .scroll-reveal-delay-2 { animation-delay: 0.2s; }
  .scroll-reveal-delay-3 { animation-delay: 0.3s; }
  .scroll-reveal-delay-4 { animation-delay: 0.4s; }
}
@supports not (animation-timeline: view()) {
  .scroll-reveal {
    animation: smoothReveal 0.85s var(--ease-spring) both;
  }
}

/* Staggered entrance animations */
.stagger-children > * {
  animation: slideUpFade 0.6s var(--ease-spring) both;
}
.stagger-children > *:nth-child(1) { animation-delay: 0.05s; }
.stagger-children > *:nth-child(2) { animation-delay: 0.1s; }
.stagger-children > *:nth-child(3) { animation-delay: 0.15s; }
.stagger-children > *:nth-child(4) { animation-delay: 0.2s; }
.stagger-children > *:nth-child(5) { animation-delay: 0.25s; }
.stagger-children > *:nth-child(6) { animation-delay: 0.3s; }

/* IntersectionObserver fallback classes */
.reveal-on-scroll { opacity: 0; transform: translateY(30px); transition: opacity 0.8s var(--ease-spring), transform 0.8s var(--ease-spring); }
.reveal-on-scroll.is-visible { opacity: 1; transform: translateY(0); }
.reveal-on-scroll.delay-1 { transition-delay: 0.1s; }
.reveal-on-scroll.delay-2 { transition-delay: 0.2s; }
.reveal-on-scroll.delay-3 { transition-delay: 0.3s; }
.reveal-on-scroll.delay-4 { transition-delay: 0.4s; }
.reveal-on-scroll.delay-5 { transition-delay: 0.5s; }

.landing {
  overflow: hidden;
  background: 
    radial-gradient(ellipse at 74% 17%, rgba(34, 43, 45, 0.25), transparent 38%),
    radial-gradient(ellipse at 20% 80%, rgba(195, 239, 131, 0.04), transparent 40%),
    radial-gradient(ellipse at 80% 20%, rgba(134, 197, 237, 0.03), transparent 35%),
    #0b0d10;
}

/* Animated background particles */
.landing::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image: 
    radial-gradient(2px 2px at 20% 30%, rgba(195, 239, 131, 0.4), transparent),
    radial-gradient(1px 1px at 40% 70%, rgba(134, 197, 237, 0.3), transparent),
    radial-gradient(1.5px 1.5px at 80% 40%, rgba(195, 239, 131, 0.2), transparent),
    radial-gradient(1px 1px at 60% 80%, rgba(238, 193, 123, 0.25), transparent);
  background-repeat: repeat;
  background-size: 400px 400px, 300px 300px, 500px 500px, 350px 350px;
  animation: floatParticle 20s ease-in-out infinite;
  opacity: 0.4;
}

.topbar, .footer, .auth-topbar {
  width: min(1192px, calc(100% - 96px));
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.topbar {
  height: 84px;
  border-bottom: 1px solid var(--line);
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 0;
  padding: 0;
  background: transparent;
  color: #f1f1ed;
  font-size: 20px;
  font-weight: 680;
  letter-spacing: -0.8px;
  cursor: pointer;
  transition: transform 0.25s var(--ease-spring);
}
.brand:hover { transform: scale(1.03); }
.brand-mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid rgba(195, 239, 131, 0.28);
  border-radius: 9px;
  background: linear-gradient(145deg, rgba(195, 239, 131, 0.2), rgba(195, 239, 131, 0.04));
  color: var(--lime);
  transition: all 0.3s var(--ease-spring);
}
.brand:hover .brand-mark {
  border-color: var(--lime);
  box-shadow: 0 0 16px rgba(195, 239, 131, 0.3);
}
.brand-period { color: var(--lime); }
.nav-links {
  display: flex;
  gap: 36px;
  margin-left: 60px;
  color: #96999e;
  font-size: 13px;
}
.nav-links a, .text-link, .back-link, .footer button {
  transition: color 0.2s var(--ease-spring), transform 0.2s var(--ease-spring);
}
.nav-links a:hover, .text-link:hover, .back-link:hover, .footer button:hover {
  color: var(--lime);
  transform: translateY(-1px);
}

.nav-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 9px 18px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  color: #e5e5e2;

