/* PLANNER ROW */
.planner-visual { position: absolute; top: 58px; right: 17px; left: 17px; }
.planner-row {
  display: flex;
  height: 26px;
  align-items: center;
  gap: 7px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  color: #9da19c;
  font-size: 8px;
  transition: transform 0.2s, color 0.2s;
}
.planner-row:hover { transform: translateX(2px); color: #e4e8dd; }
.task-check {
  display: grid;
  width: 12px;
  height: 12px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 4px;
  transition: all 0.2s var(--ease-spring);
}
.planner-row.done { color: #6a716c; text-decoration: line-through; }
.planner-row.done .task-check {
  border-color: var(--lime);
  background: var(--lime);
  color: #11140e;
  animation: scaleIn 0.3s var(--ease-spring);
}

/* COMPARISON TABLE */
.comparison-section {
  background: radial-gradient(ellipse at 50% 0%, rgba(195, 239, 131, 0.03), transparent 50%);
}
.overflow-x-auto {
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: #111419;
}
table {
  width: 100%;
  border-collapse: collapse;
}
thead tr {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent);
}
th, td {
  padding: 16px 20px;
  font-size: 13px;
}
th {
  color: #8c9194;
  font-weight: 500;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  font-size: 11px;
}
tbody tr {
  transition: background 0.2s var(--ease-spring);
}
tbody tr:hover {
  background: rgba(195, 239, 131, 0.02);
}
tbody tr td:first-child {
  font-weight: 500;
  color: #f1f0ec;
}
tbody td {
  color: #9da19c;
  border-top: 1px solid var(--line);
}
tbody td.font-bold { color: var(--lime); }
tbody td.border-x {
  background: rgba(195, 239, 131, 0.03);
}

/* FAQ */
#faq {
  background: radial-gradient(ellipse at 50% 50%, rgba(195, 239, 131, 0.02), transparent 60%);
}
#faq .space-y-3 > div {
  transition: all 0.3s var(--ease-spring);
  backdrop-filter: blur(10px);
}
#faq .space-y-3 > div:hover {
  border-color: rgba(195, 239, 131, 0.3);
  background: rgba(195, 239, 131, 0.02);
  transform: translateX(4px);
}

/* CLOSING CTA */
.closing-cta {
  position: relative;
  display: flex;
  min-height: 380px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  text-align: center;
  background: 
    radial-gradient(ellipse at center, rgba(195, 239, 131, 0.08), transparent 60%),
    radial-gradient(ellipse at 20% 20%, rgba(134, 197, 237, 0.04), transparent 40%),
    radial-gradient(ellipse at 80% 80%, rgba(238, 193, 123, 0.03), transparent 40%);
}
.closing-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  background: 
    radial-gradient(2px 2px at 10% 20%, rgba(195, 239, 131, 0.3), transparent),
    radial-gradient(1px 1px at 90% 80%, rgba(134, 197, 237, 0.2), transparent),
    radial-gradient(1.5px 1.5px at 50% 50%, rgba(195, 239, 131, 0.15), transparent);
  background-size: 300px 300px, 250px 250px, 400px 400px;
  animation: floatParticle 25s ease-in-out infinite;
  pointer-events: none;
  opacity: 0.6;
}
.closing-cta h2 {
  margin: 14px 0 10px;
  color: #eceee7;
  font-size: 40px;
  font-weight: 550;
  letter-spacing: -1.8px;
}
.closing-cta > p { margin: 0 0 22px; color: #939895; font-size: 13px; }

/* FOOTER */
.footer { 
  min-height: 75px; 
  color: #73787d; 
  font-size: 11px;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(20px);
}

/* AUTH */
.auth-page { 
  min-height: 100vh; 
  background: #0b0d10;
  position: relative;
}
.auth-page::before {
  content: '';
