  transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}
.back-link:hover svg {
  border-color: rgba(195, 239, 131, 0.17);
  background: rgba(195, 239, 131, 0.08);
  transform: translateX(-1px);
}
.kbd-shortcut {
