function Brand({ onClick }: { onClick: () => void }) {
  return (
    <button className="brand" type="button" onClick={onClick} aria-label="Synapse home">
      <span className="brand-mark"><Icon name="spark" size={19} /></span>
      <span>synapse<span className="brand-period">.</span></span>
    </button>
  );
}

function LandingPage({ onGetStarted }: { onGetStarted: () => void }) {
  const [flashFlipped, setFlashFlipped] = useState(false);
  const [activeUnit, setActiveUnit] = useState<1 | 2 | 3>(1);
  const [quizSelected, setQuizSelected] = useState<number | null>(null);
  const [playingAudio, setPlayingAudio] = useState(false);
  const landingRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const landing = landingRef.current;
    if (!landing) return;

    const elements = Array.from(
      landing.querySelectorAll<HTMLElement>(".reveal-on-scroll"),
    );
    const showEverything = () => {
      elements.forEach((element) => element.classList.add("is-visible"));
    };

    if (
      window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
      !("IntersectionObserver" in window)
    ) {
      showEverything();
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.01, rootMargin: "0px 0px -8% 0px" },
    );

    elements.forEach((element) => {
      const bounds = element.getBoundingClientRect();
      if (bounds.bottom <= 0 || bounds.top < window.innerHeight) {
        element.classList.add("is-visible");
      } else {
        observer.observe(element);
      }
    });

