result.content:
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.035);
  color: #e5e5e2;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s var(--ease-spring);
  position: relative;
  overflow: hidden;
}
.google-button::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(195, 239, 131, 0.1), transparent);
  transform: translateX(-100%);
  transition: transform 0.4s ease;
}
.google-button:hover {
  border-color: rgba(195, 239, 131, 0.5);
  background: rgba(195, 239, 131, 0.08);
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(195, 239, 131, 0.15);
}
.google-button:hover::before {
  transform: translateX(100%);
}
.google-button:disabled, .button-primary:disabled {
  cursor: wait;
  opacity: 0.7;
  transform: none;
}
.input-wrap {
  display: flex;
  height: 42px;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.25);
  transition: border-color 0.25s var(--ease-spring), box-shadow 0.25s var(--ease-spring);
}
.input-wrap:focus-within {
  border-color: var(--lime);
  box-shadow: 0 0 15px rgba(195, 239, 131, 0.15), 0 0 0 1px rgba(195, 239, 131, 0.1) inset;
}
.input-wrap input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #ffffff;
  font-size: 12px;
}
.input-wrap input::placeholder { color: #5d626a; }
.form-message {
  color: #f87171;
  font-size: 11px;
  animation: slideUpFade 0.3s var(--ease-spring);
}
.auth-panel button.button-primary { margin-top: 4px; }

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; gap: 40px; }
  .bento-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
  .flash-card, .quiz-card, .audio-card, .mindmap-card, .planner-card { grid-column: 1; grid-row: auto; min-height: 280px; }
  .auth-layout { grid-template-columns: 1fr; gap: 40px; }
  .auth-aside::before { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
  .landing.reveal-enabled .reveal-on-scroll:not(.is-visible) {
    opacity: 1;
    transform: none;
  }
}

