              <path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-1.9-5.8L4 11l6.1-2.2L12 3Z" />
            </svg>
          </span>
          <span>synapse<span className="brand-period">.</span></span>
        </Link>

        <div className="flex items-center gap-3">
          <div className="social-proof !mt-0 !py-1 !px-3 text-xs">
            <span className="live-dot" />
            <span>{providerName} · <b>Active Session</b></span>
          </div>
          <button
            type="button"
            className="nav-cta"
            onClick={handleSignOut}
          >
            Sign out
          </button>
        </div>
      </header>

      {/* Main Workspace Dashboard Container */}
      <div className="w-[min(1192px,calc(100%-64px))] mx-auto py-12">
        {/* Welcome Banner */}
        <div className="mb-10 animate-entrance">
          <div className="eyebrow mb-2">
            <span className="live-dot" /> VERIFIED STUDENT COCKPIT
          </div>
          <h1 className="text-3xl sm:text-5xl font-medium tracking-tight text-[#f1f0ec] mb-3">
            Welcome to your study space, <span className="text-[#c3ef83]">{userName} ✳</span>
          </h1>
          <p className="text-[#8c9194] text-xs sm:text-sm max-w-xl leading-relaxed">
            Your notes, progressive learn units, and Notion schedule are synced. Pick up where you left off or start a new focus session.
          </p>
        </div>

        {/* User Status Bento Card */}
        <div className="p-6 sm:p-8 rounded-xl border border-[rgba(255,255,255,0.08)] bg-[#111419] mb-8">
          <div className="flex flex-col sm:flex-row items-center sm:items-start gap-5 border-b border-[rgba(255,255,255,0.06)] pb-6 mb-6">
            <div className="w-16 h-16 rounded-xl border border-[rgba(195,239,131,0.4)] bg-[#182216] text-[#c3ef83] flex items-center justify-center text-2xl font-bold shadow-[0_0_20px_rgba(195,239,131,0.15)]">
              {userName.charAt(0).toUpperCase()}
