   ═══════════════════════════════════════════════════════ */
.dashboard-shell {
  --dash-bg: #0b0d10;
  --dash-panel: #14181e;
  --dash-card: linear-gradient(145deg, rgba(22, 26, 31, 0.94), rgba(16, 19, 23, 0.98));
  --dash-border: rgba(255, 255, 255, 0.08);
  --dash-border-hover: rgba(195, 239, 131, 0.4);
  --dash-text: #f1f0ec;
  --dash-muted: #8c9194;
  --dash-subtle: #5d626a;
  --dash-lime: #c3ef83;
  --dash-lime-glow: rgba(195, 239, 131, 0.25);
  --dash-coral: #f47d69;
  --dash-cyan: #86c5ed;
  display: flex;
  min-height: 100vh;
  background:
    radial-gradient(ellipse at 80% 12%, rgba(195, 239, 131, 0.04), transparent 40%),
    radial-gradient(ellipse at 15% 85%, rgba(134, 197, 237, 0.03), transparent 40%),
    #0b0d10;
  color: var(--dash-text);
  position: relative;
  overflow-x: hidden;
}

/* Subtle background particle ambience in dashboard */
.dashboard-shell::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image: 
    radial-gradient(2px 2px at 20% 30%, rgba(195, 239, 131, 0.35), transparent),
    radial-gradient(1px 1px at 40% 70%, rgba(134, 197, 237, 0.25), transparent),
    radial-gradient(1.5px 1.5px at 80% 40%, rgba(195, 239, 131, 0.18), transparent);
  background-repeat: repeat;
  background-size: 400px 400px, 300px 300px, 500px 500px;
  animation: floatParticle 22s ease-in-out infinite;
  opacity: 0.35;
}

/* Sidebar */
.dashboard-sidebar {
  position: sticky;
  top: 0;
  display: flex;
  width: 240px;
  height: 100vh;
  flex: 0 0 240px;
  flex-direction: column;
  padding: 22px 16px 18px;
  border-right: 1px solid var(--dash-border);
  background: rgba(14, 17, 22, 0.88);
  backdrop-filter: blur(20px);
  z-index: 10;
}
.dashboard-brand {
  display: flex;
  height: 42px;
  align-items: center;
  gap: 10px;
  margin: 0 8px 36px;
  color: #f1f0ec;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.8px;
  transition: transform 0.25s var(--ease-spring);
}
.dashboard-brand:hover {
  transform: scale(1.02);
}
.dashboard-brand > span:last-child > span {
  color: var(--dash-lime);
}
.dashboard-brand-mark {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid rgba(195, 239, 131, 0.28);
  border-radius: 9px;
  background: linear-gradient(145deg, rgba(195, 239, 131, 0.15), rgba(195, 239, 131, 0.03));
  color: var(--dash-lime);
  transition: all 0.3s var(--ease-spring);
}
.dashboard-brand:hover .dashboard-brand-mark {
  border-color: var(--dash-lime);
  box-shadow: 0 0 16px rgba(195, 239, 131, 0.35);
  transform: rotate(8deg);
}
.sidebar-label {
  margin: 0 10px 10px;
  color: #6b7280;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.4px;
}
.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.sidebar-link {
  display: flex;
  height: 42px;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: #9da19c;
  font-size: 12px;
  font-weight: 550;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.sidebar-link:hover {
  background: rgba(195, 239, 131, 0.06);
  color: #ffffff;
  transform: translateX(3px);
  border-color: rgba(195, 239, 131, 0.15);
}
.sidebar-link.active {
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
  border-color: rgba(195, 239, 131, 0.3);
  font-weight: 650;
  box-shadow: 0 0 15px rgba(195, 239, 131, 0.08);
}
.sidebar-link.active svg {
  color: var(--dash-lime);
  filter: drop-shadow(0 0 6px rgba(195, 239, 131, 0.5));
}
.nav-new {
  margin-left: auto;
  padding: 2px 6px;
  border-radius: 5px;
  background: rgba(195, 239, 131, 0.15);
  color: var(--dash-lime);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.5px;
  border: 1px solid rgba(195, 239, 131, 0.25);
}
.sidebar-spacer {
  flex: 1;
}
.sidebar-note {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  overflow: hidden;
  margin: 0 2px 16px;
  padding: 12px 12px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(22, 26, 31, 0.9), rgba(16, 19, 23, 0.95));
  transition: border-color 0.25s, box-shadow 0.25s;
}
.sidebar-note:hover {
  border-color: rgba(195, 239, 131, 0.3);
  box-shadow: 0 0 20px rgba(195, 239, 131, 0.06);
}
.sidebar-note-icon {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  place-items: center;
  border-radius: 8px;
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
}
.sidebar-note p {
  margin: 0;
  color: #858b8e;
  font-size: 9px;
  line-height: 1.5;
}
.sidebar-note p b {
  color: #f1f0ec;
  font-size: 10px;
}
.sidebar-note-spark {
  position: absolute;
  top: 6px;
  right: 8px;
  color: var(--dash-lime);
  font-size: 13px;
  animation: softPulse 2s ease-in-out infinite;
}
.sidebar-footer {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 4px 0;
  border-top: 1px solid var(--dash-border);
}
.open-source-mark {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 1px solid rgba(195, 239, 131, 0.2);
  border-radius: 50%;
  color: var(--dash-lime);
  font-size: 12px;
  background: rgba(195, 239, 131, 0.05);
}
.sidebar-footer > span:nth-child(2) {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
}
.sidebar-footer b {
  color: #d5d8d1;
  font-size: 9px;
  font-weight: 600;
}
.sidebar-footer small {
  color: #6b7280;
  font-size: 8px;
}
.coral-heart {
  color: #f47d69;
  font-size: 12px;
  animation: softPulse 2s ease-in-out infinite;
}

/* Dashboard Main */
.dashboard-main {
  min-width: 0;
  flex: 1;
  position: relative;
  z-index: 1;
}
.dashboard-topbar {
  position: sticky;
  z-index: 20;
  top: 0;
  display: flex;
  height: 68px;
  align-items: center;
  justify-content: space-between;
  padding: 0 clamp(24px, 4vw, 56px);
  border-bottom: 1px solid var(--dash-border);
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: blur(20px);
}
.topbar-crumb {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #8c9194;
  font-size: 12px;
  font-weight: 550;
}
.crumb-home {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--dash-lime);
}

