@keyframes loaderRevealOut {
  0% { clip-path: inset(0 0 0 0); opacity: 1; }
  100% { clip-path: inset(0 0 100% 0); opacity: 0; }
}

.loading-screen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #060810;
  overflow: hidden;
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.loading-screen.is-revealing {
  animation: loaderRevealOut 0.6s cubic-bezier(0.77, 0, 0.175, 1) forwards;
}

/* Ambient orbs */
.loader-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
}
.loader-orb-1 {
  width: 300px; height: 300px;
  top: 20%; left: 15%;
  background: rgba(195, 239, 131, 0.15);
  animation: loaderOrb1 6s ease-in-out infinite;
}
.loader-orb-2 {
  width: 250px; height: 250px;
  bottom: 20%; right: 15%;
  background: rgba(134, 197, 237, 0.12);
  animation: loaderOrb2 7s ease-in-out infinite;
}
.loader-orb-3 {
  width: 200px; height: 200px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(238, 193, 123, 0.08);
  animation: loaderOrb3 5s ease-in-out infinite;
}

/* Particles */
.loader-particles { position: absolute; inset: 0; pointer-events: none; }
.loader-particle {
  position: absolute;
  width: 3px; height: 3px;
  border-radius: 50%;
  background: rgba(195, 239, 131, 0.5);
  animation: loaderParticleFloat 3s ease-in-out infinite;
}
.loader-particle:nth-child(even) {
  background: rgba(134, 197, 237, 0.4);
  width: 2px; height: 2px;
}
.loader-particle:nth-child(3n) {
  background: rgba(238, 193, 123, 0.35);
  width: 2.5px; height: 2.5px;
}

/* Animated rings */
.loader-rings {
  position: absolute;
  width: 200px; height: 200px;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
}
.loader-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid transparent;
}
.loader-ring-outer {
  inset: 0;
  border-top-color: rgba(195, 239, 131, 0.4);
  border-right-color: rgba(195, 239, 131, 0.1);
  animation: loaderRingSpin 3s linear infinite;
}
.loader-ring-middle {
  inset: 20px;
  border-bottom-color: rgba(134, 197, 237, 0.3);
  border-left-color: rgba(134, 197, 237, 0.08);
  animation: loaderRingSpinReverse 2.5s linear infinite;
}
.loader-ring-inner {
  inset: 40px;
  border-top-color: rgba(238, 193, 123, 0.25);
  border-right-color: rgba(238, 193, 123, 0.06);
  animation: loaderRingSpin 2s linear infinite;
}

/* Center brand */
.loader-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}
.loader-brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.loader-brand-icon {
  display: grid;
  width: 56px; height: 56px;
  place-items: center;
  border: 1px solid rgba(195, 239, 131, 0.3);
  border-radius: 16px;
  background: linear-gradient(145deg, rgba(195, 239, 131, 0.15), rgba(195, 239, 131, 0.04));
  color: #c3ef83;
  animation: loaderBrandPulse 2s ease-in-out infinite;
}
.loader-brand-text {
  color: #f1f1ed;
  font-size: 26px;
  font-weight: 680;
  letter-spacing: -1px;
}
.loader-brand-text span { color: #c3ef83; }

/* Progress bar */
.loader-progress {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 220px;
}
.loader-progress-track {
  position: relative;
  flex: 1;
  height: 3px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.loader-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #c3ef83, #86c5ed);
  transition: width 0.15s ease-out;
  position: relative;
}
.loader-progress-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
  animation: loaderProgressShimmer 1.5s ease-in-out infinite;
}
.loader-progress-glow {
  position: absolute;
  top: 50%;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: rgba(195, 239, 131, 0.6);
  filter: blur(8px);
  transform: translate(-50%, -50%);
  transition: left 0.15s ease-out;
  pointer-events: none;
}
.loader-progress-text {
  color: rgba(195, 239, 131, 0.8);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  min-width: 32px;
  text-align: right;
}

/* Status */
.loader-status {
  color: #6b7280;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.3px;
  margin: 0;
  transition: opacity 0.3s;
}

/* Scanline */
.loader-scanline {
  position: absolute;
  left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(195, 239, 131, 0.3), transparent);
  animation: loaderScanline 3s ease-in-out infinite;
  pointer-events: none;
}


/* ═══════════════════════════════════════════════════════
   ENHANCED SCROLL ANIMATIONS & GLOW EFFECTS
   ═══════════════════════════════════════════════════════ */

/* Magnetic cursor glow on feature cards */
.feature-card {
  --glow-x: 50%;
  --glow-y: 50%;
}
.feature-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    400px circle at var(--glow-x) var(--glow-y),
    rgba(195, 239, 131, 0.08),
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
  z-index: 0;
}
.feature-card:hover::after {
  opacity: 1;
}

/* Staggered bento card reveals */
.feature-card {
  transition: all 0.5s var(--ease-spring), opacity 0.7s ease, transform 0.7s var(--ease-spring);
}
.landing.reveal-enabled .feature-card:not(.is-revealed) {
  opacity: 0;
  transform: translateY(40px) scale(0.95);
}
.feature-card.is-revealed {
  opacity: 1 !important;
  transform: translateY(0) scale(1);

