  font-size: 12px;
  font-weight: 500;
}
.play-icon {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  color: var(--lime);
  transition: all 0.2s var(--ease-spring);
}
.text-link:hover .play-icon {
  border-color: var(--lime);
  transform: scale(1.1);
  box-shadow: 0 0 16px rgba(195, 239, 131, 0.3);
}

.social-proof {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 36px;
  padding: 8px 16px 8px 10px;
  border: 1px solid rgba(195, 239, 131, 0.25);
  border-radius: 9999px;
  background: rgba(195, 239, 131, 0.05);
  box-shadow: 0 0 24px rgba(195, 239, 131, 0.08);
  color: #a4a8ad;
  font-size: 11px;
  transition: all 0.3s var(--ease-spring);
}
.social-proof:hover {
  border-color: rgba(195, 239, 131, 0.45);
  box-shadow: 0 0 32px rgba(195, 239, 131, 0.15);
  transform: translateY(-2px);
}
.social-proof b {
  color: var(--lime);
  font-weight: 650;
}
.avatar-stack { display: flex; padding-left: 2px; }
.avatar-stack span {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  margin-left: -4px;
  border: 2px solid #0b0d10;
  border-radius: 50%;
  background: #252b22;
  color: var(--lime);
  font-size: 9px;
  font-weight: bold;
  transition: transform 0.3s var(--ease-spring);
}
.avatar-stack span:hover {
  transform: scale(1.15) translateY(-2px);
  z-index: 10;
}
.avatar-stack span:nth-child(2) { background: #1a2228; color: #86c5ed; }
.avatar-stack span:nth-child(3) { background: #28221b; color: #eec17b; }
.avatar-stack span:nth-child(4) { background: #271f28; color: #e9939e; }

.hero-art {
  position: relative;
  display: flex;
  min-height: 446px;
  align-items: center;
  justify-content: center;
  isolation: isolate;
  animation: floatSmooth 6.5s ease-in-out infinite;
}
.ambient {
  position: absolute;
  z-index: -2;
  border-radius: 50%;
  filter: blur(65px);
  pointer-events: none;
  animation: pulseGlow 4.5s ease-in-out infinite alternate;
}
.ambient-one {
  top: 60px;
  right: 12%;
  width: 280px;
  height: 280px;
  background: rgba(195, 239, 131, 0.12);
}
.ambient-two {
  right: -5%;
  bottom: 30px;
  width: 240px;
  height: 220px;
  background: rgba(134, 197, 237, 0.09);
}
.ambient-three {
  left: -5%;
  top: 30%;
  width: 200px;
  height: 200px;
  background: rgba(238, 193, 123, 0.08);
  animation-delay: -1.5s;
}
.orbit {
  position: absolute;
  z-index: -1;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 50%;
  transform: rotate(-19deg);
  animation: orbitRotate 20s linear infinite;
}
.orbit-one { width: 570px; height: 270px; }
.orbit-two { width: 480px; height: 212px; transform: rotate(31deg); animation-direction: reverse; animation-duration: 25s; }
.orbit-three { width: 380px; height: 160px; transform: rotate(-45deg); top: 20%; left: 10%; animation-duration: 30s; border-color: rgba(195, 239, 131, 0.08); }

@keyframes orbitRotate {
  from { transform: rotate(-19deg); }
  to { transform: rotate(341deg); }
}

.preview-window {
  position: relative;
  z-index: 1;
  width: min(432px, 92%);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 14px;
  background: linear-gradient(150deg, #161a20 0%, #101318 100%);
  box-shadow: 
    0 25px 75px rgba(0, 0, 0, 0.55), 
    0 0 50px rgba(195, 239, 131, 0.08),
    0 0 0 1px rgba(195, 239, 131, 0.05) inset;
  transform: perspective(1000px) rotateY(-5deg) rotateX(2deg);
  transition: transform 0.5s var(--ease-spring), box-shadow 0.5s var(--ease-spring);
}
.preview-window:hover {
  transform: perspective(1000px) rotateY(0deg) rotateX(0deg) translateY(-4px);
  box-shadow: 
    0 35px 85px rgba(0, 0, 0, 0.65), 
    0 0 60px rgba(195, 239, 131, 0.14),
    0 0 0 1px rgba(195, 239, 131, 0.15) inset;
}
.preview-topbar {
  display: flex;
  height: 43px;
  align-items: center;
  justify-content: space-between;
  padding: 0 15px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px);
}
.window-dots { display: flex; gap: 4px; }
.window-dots i { width: 6px; height: 6px; border-radius: 50%; background: #4d5054; }
.window-dots i:first-child { background: #bc746b; }
.window-dots i:nth-child(2) { background: #c5a767; }
.window-dots i:nth-child(3) { background: #718d65; }
.preview-title { margin-left: 18px; color: #898c90; font-size: 10px; }
.preview-avatar {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 7px;
