   background: radial-gradient(ellipse at 50% 50%, rgba(195, 239, 131, 0.02), transparent 60%);
 }
 #faq .space-y-3 > div {
   transition: all 0.3s var(--ease-spring);
   backdrop-filter: blur(10px);
 }
 #faq .space-y-3 > div:hover {
   border-color: rgba(195, 239, 131, 0.3);
   background: rgba(195, 239, 131, 0.02);
   transform: translateX(4px);
 }

 /* CLOSING CTA */
 .closing-cta {
   position: relative;
   display: flex;
   min-height: 380px;
   flex-direction: column;
   align-items: center;
   justify-content: center;
   overflow: hidden;
   border-top: 1px solid var(--line);
   border-bottom: 1px solid var(--line);
   text-align: center;
   background: 
     radial-gradient(ellipse at center, rgba(195, 239, 131, 0.08), transparent 60%),
     radial-gradient(ellipse at 20% 20%, rgba(134, 197, 237, 0.04), transparent 40%),
     radial-gradient(ellipse at 80% 80%, rgba(238, 193, 123, 0.03), transparent 40%);
 }
 .closing-cta::before {
   content: '';
   position: absolute;
   inset: 0;
   background: 
     radial-gradient(2px 2px at 10% 20%, rgba(195, 239, 131, 0.3), transparent),
     radial-gradient(1px 1px at 90% 80%, rgba(134, 197, 237, 0.2), transparent),
     radial-gradient(1.5px 1.5px at 50% 50%, rgba(195, 239, 131, 0.15), transparent);
   background-size: 300px 300px, 250px 250px, 400px 400px;
   animation: floatParticle 25s ease-in-out infinite;
   pointer-events: none;
   opacity: 0.6;
 }
 .closing-cta h2 {
   margin: 14px 0 10px;
   color: #eceee7;
   font-size: 40px;
   font-weight: 550;
   letter-spacing: -1.8px;
 }
 .closing-cta > p { margin: 0 0 22px; color: #939895; font-size: 13px; }

 /* FOOTER */
 .footer { 
   min-height: 75px; 
   color: #73787d; 
   font-size: 11px;
   background: rgba(0, 0, 0, 0.2);
   backdrop-filter: blur(20px);
 }

 /* AUTH */
 .auth-page { 
   min-height: 100vh; 
   background: #0b0d10;
   position: relative;
 }
 .auth-page::before {
   content: '';
   position: fixed;

result.content:
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: blur(20px);
}
.topbar-crumb {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #8c9194;
  font-size: 12px;
  font-weight: 550;
}
.crumb-home {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--dash-lime);
}
.topbar-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}
.account-provider {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: #9da19c;
  font-size: 9px;
  font-weight: 550;
}
.account-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--dash-lime);
  box-shadow: 0 0 10px rgba(195, 239, 131, 0.6);
  animation: softPulse 2s ease-in-out infinite;
}
.profile-wrap {
  position: relative;
}
.profile-button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 8px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: #d5d8d1;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.profile-button:hover {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.08);
}
.profile-avatar {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid rgba(195, 239, 131, 0.35);
  border-radius: 50%;
  background: linear-gradient(145deg, rgba(195, 239, 131, 0.2), rgba(195, 239, 131, 0.04));
  color: var(--dash-lime);
  font-size: 12px;
  font-weight: 700;
  box-shadow: 0 0 12px rgba(195, 239, 131, 0.2);
}
.profile-name {
  max-width: 130px;
  overflow: hidden;
  font-size: 11px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.profile-button > svg {
  color: #71777d;
  transform: rotate(90deg);
  transition: transform 0.2s;
}
.profile-wrap[aria-expanded="true"] .profile-button > svg {
  transform: rotate(-90deg);
}
.profile-menu {
  position: absolute;
  top: 46px;
  right: 0;
  z-index: 30;
  display: flex;
  width: 220px;
  flex-direction: column;
  gap: 6px;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  background: linear-gradient(150deg, #181d24, #12151b);
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.6), 0 0 30px rgba(195, 239, 131, 0.08);
  animation: slideUpFade 0.25s var(--ease-spring);
  backdrop-filter: blur(20px);
}
.profile-menu > b {
  color: #f1f0ec;
  font-size: 12px;
  font-weight: 600;
}
.profile-menu > span {
  overflow: hidden;
  color: #858b8e;
  font-size: 9px;
  text-overflow: ellipsis;
}
.profile-menu button {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  color: #f47d69;
  font-size: 10px;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.profile-menu button:hover {
  border-color: rgba(244, 125, 105, 0.4);
  background: rgba(244, 125, 105, 0.08);
  transform: translateY(-1px);
}
.profile-menu button:disabled {
  cursor: wait;
  opacity: 0.6;
}

/* Dashboard Content */
.dashboard-content {
  position: relative;
  width: min(1220px, 100%);
  margin: 0 auto;
  padding: 38px clamp(24px, 4vw, 56px) 60px;
}
.dashboard-welcome {
  position: relative;
  display: flex;
  min-height: 190px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  animation: smoothReveal 0.8s var(--ease-spring) both;
}
.welcome-copy {
  position: relative;
  z-index: 1;
  max-width: 510px;
  padding: 4px 0;
}
.dashboard-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #8c9194;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
}
.dashboard-eyebrow > span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--dash-lime);
  box-shadow: 0 0 10px rgba(195, 239, 131, 0.7);
  animation: softPulse 2s ease-in-out infinite;
}
.welcome-copy h1 {
  margin: 14px 0 10px;
  color: #f1f0ec;
  font-size: clamp(34px, 4vw, 48px);
  font-weight: 650;
  letter-spacing: -2px;
  line-height: 1.08;
}
.welcome-copy h1 > span {
  color: var(--dash-lime);
  animation: textGlow 3s ease-in-out infinite;
}
.welcome-copy p {
  max-width: 440px;
  margin: 0;
  color: #8c9194;
  font-size: 12px;
  line-height: 1.7;
}
.welcome-art-wrap {
  position: absolute;
  top: 0;
  right: 24%;
  width: 246px;
  height: 186px;
  animation: floatSmooth 6s ease-in-out infinite;
  pointer-events: none;
}
.study-illustration {
  position: absolute;
  z-index: 1;
  right: 8px;
  bottom: -6px;
  width: 210px;
  height: 166px;
  filter: drop-shadow(0 12px 25px rgba(0, 0, 0, 0.5));
}
.welcome-art-orbit {
  position: absolute;
  top: 25px;
  left: 25px;
  width: 190px;
  height: 115px;
  border: 1px solid rgba(195, 239, 131, 0.16);
  border-radius: 50%;
  transform: rotate(-17deg);
  animation: orbitRotate 24s linear infinite;
}
.welcome-art-orbit.orbit-b {
  top: 43px;
  left: 41px;
  width: 158px;
  height: 84px;
  border-color: rgba(134, 197, 237, 0.16);
  transform: rotate(32deg);
  animation-direction: reverse;
  animation-duration: 20s;
}
.welcome-speech {
  position: absolute;
  z-index: 2;
  top: 0;
  right: 4px;
  padding: 6px 11px;
  border: 1px solid rgba(195, 239, 131, 0.3);
  border-radius: 10px 10px 10px 2px;
  background: rgba(22, 26, 31, 0.95);
  color: var(--dash-lime);
  font-size: 9px;
  font-weight: 650;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4), 0 0 15px rgba(195, 239, 131, 0.1);
  backdrop-filter: blur(10px);
}
.encouragement-card {
  position: relative;
  z-index: 2;
  display: flex;
  min-width: 210px;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.9), rgba(16, 19, 23, 0.95));
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(14px);
  transition: all 0.25s var(--ease-spring);
}
.encouragement-card:hover {
  transform: translateY(-2px);
  border-color: rgba(195, 239, 131, 0.35);
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.5), 0 0 20px rgba(195, 239, 131, 0.08);
}
.encouragement-icon {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  place-items: center;
  border-radius: 9px;
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
}
.encouragement-card > span:nth-child(2) {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
}
.encouragement-card b {
  color: #f1f0ec;
  font-size: 10px;
}
.encouragement-card small {
  color: #8c9194;
  font-size: 8px;
}
.encouragement-bars {
  display: flex;
  height: 23px;
  align-items: flex-end;
  gap: 3px;
}
.encouragement-bars i {
  width: 4px;
  border-radius: 3px 3px 1px 1px;
  background: rgba(195, 239, 131, 0.35);
}
.encouragement-bars i:nth-child(1) { height: 9px; }
.encouragement-bars i:nth-child(2) { height: 15px; }
.encouragement-bars i:nth-child(3) { height: 21px; background: var(--dash-lime); box-shadow: 0 0 8px rgba(195, 239, 131, 0.6); }

/* Study Prompt Card */
.study-prompt-card {
  position: relative;
  z-index: 1;
  margin-bottom: 18px;
  padding: 20px 22px 18px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.94), rgba(16, 19, 23, 0.98));
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.45), 0 0 35px rgba(195, 239, 131, 0.05);
  backdrop-filter: blur(20px);
  transition: border-color 0.3s var(--ease-spring), box-shadow 0.3s;
}
.study-prompt-card:focus-within {
  border-color: rgba(195, 239, 131, 0.35);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.55), 0 0 45px rgba(195, 239, 131, 0.1);
}
.prompt-tip {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  color: #8c9194;
  font-size: 10px;
  font-weight: 500;
}
.prompt-tip svg {
  color: var(--dash-lime);
}
.prompt-form {
  display: flex;
  height: 46px;
  align-items: center;
  gap: 12px;
}
.prompt-form input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: none;
  background: transparent;
  color: #ffffff;
  font-size: 13px;
  font-weight: 500;
}
.prompt-form input::placeholder {
  color: #5d626a;
}
.prompt-submit {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  place-items: center;
  border: 1px solid rgba(214, 245, 171, 0.6);
  border-radius: 50%;
  background: var(--dash-lime);
  color: #11140e;
  box-shadow: 0 0 20px rgba(195, 239, 131, 0.3);
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.prompt-submit:hover:not(:disabled) {
  transform: scale(1.08);
  background: #d4f89d;
  box-shadow: 0 0 30px rgba(195, 239, 131, 0.5);
}
.prompt-submit:disabled {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.05);
  color: #5d626a;
  cursor: not-allowed;
  box-shadow: none;
}
.prompt-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
}
.source-action {
  display: inline-flex;
  height: 32px;
  align-items: center;
  gap: 7px;
  padding: 0 13px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: #c5c8c0;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.source-action:hover, .source-action.selected {
  transform: translateY(-2px);
  border-color: rgba(195, 239, 131, 0.4);
  background: rgba(195, 239, 131, 0.08);
  color: #ffffff;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}
.source-action.record-action {
  border-color: rgba(244, 125, 105, 0.25);
  background: rgba(244, 125, 105, 0.05);
  color: #f47d69;
}
.source-action.record-action:hover {
  border-color: rgba(244, 125, 105, 0.5);
  background: rgba(244, 125, 105, 0.12);
  color: #ffffff;
}
.prompt-hint {
  margin-left: auto;
  color: #6b7280;
  font-size: 9px;
}
.youtube-form {
  display: flex;
  gap: 8px;
  margin-top: 14px;
  padding-top: 13px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}
.youtube-form input {
  min-width: 0;
  flex: 1;
  padding: 10px 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  outline: none;
  background: rgba(0, 0, 0, 0.3);
  color: #ffffff;
  font-size: 11px;
  transition: border-color 0.2s;
}
.youtube-form input:focus {
  border-color: var(--dash-lime);
  box-shadow: 0 0 15px rgba(195, 239, 131, 0.15);
}
.youtube-form button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid rgba(214, 245, 171, 0.5);
  border-radius: 8px;
  background: var(--dash-lime);
  color: #11140e;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.youtube-form button:hover {
  background: #d4f89d;
  transform: translateY(-1px);
}

/* Resume Banner */
.resume-banner {
  display: flex;
  min-height: 54px;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin-bottom: 32px;
  padding: 10px 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.8), rgba(16, 19, 23, 0.9));
  color: #c5c8c0;
  text-align: left;
  cursor: pointer;
  transition: all 0.25s var(--ease-spring);
}
.resume-banner:hover {
  transform: translateY(-2px);
  border-color: rgba(195, 239, 131, 0.35);
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.45), 0 0 25px rgba(195, 239, 131, 0.08);
}
.resume-icon {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  place-items: center;
  border-radius: 8px;
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
}
.resume-label {
  color: #8c9194;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.1px;
}
.resume-banner > b {
  overflow: hidden;
  color: #f1f0ec;
  font-size: 11px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.resume-chapter {
  padding-left: 12px;
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  color: #8c9194;
  font-size: 10px;
  white-space: nowrap;
}
.resume-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  color: var(--dash-lime);
  font-size: 10px;
  font-weight: 650;
  white-space: nowrap;
  transition: transform 0.2s;
}
.resume-banner:hover .resume-link {
  transform: translateX(3px);
}

/* Notebooks Section */
.notebooks-section {
  scroll-margin-top: 85px;
}
.notebooks-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}
.notebooks-title {
  display: flex;
  align-items: center;
  gap: 12px;
}
.notebooks-title-icon {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid rgba(195, 239, 131, 0.25);
  border-radius: 10px;
  background: rgba(195, 239, 131, 0.08);
  color: var(--dash-lime);
}
.notebooks-title h2 {
  margin: 0;
  color: #f1f0ec;
  font-size: 20px;
  font-weight: 650;
  letter-spacing: -0.6px;
}
.notebooks-title p {
  margin: 3px 0 0;
  color: #8c9194;
  font-size: 10px;
}
.notebook-tools {
  display: flex;
  align-items: center;
  gap: 10px;
}
.notebook-search {
  display: flex;
  width: 220px;
  height: 38px;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: #8c9194;
  transition: all 0.2s var(--ease-spring);
}
.notebook-search:focus-within {
  border-color: var(--dash-lime);
  box-shadow: 0 0 18px rgba(195, 239, 131, 0.15);
  background: rgba(0, 0, 0, 0.3);
}
.notebook-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: #ffffff;
  font-size: 10px;
}
.notebook-search input::placeholder {
  color: #5d626a;
}
.notebook-search button {
  display: grid;
  width: 20px;
  height: 20px;
  place-items: center;
  border: 0;
  background: transparent;
  color: #8c9194;
  cursor: pointer;
}
.new-notebook-button {
  display: inline-flex;
  height: 38px;
  align-items: center;
  gap: 8px;
  padding: 0 16px;
  border: 1px solid rgba(214, 245, 171, 0.5);
  border-radius: 999px;
  background: var(--dash-lime);
  color: #11140e;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 0 20px rgba(195, 239, 131, 0.25);
  transition: all 0.2s var(--ease-spring);
}
.new-notebook-button:hover {
  transform: translateY(-2px);
  background: #d4f89d;
  box-shadow: 0 0 30px rgba(195, 239, 131, 0.4);
}
.notebooks-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.notebook-card {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 152px;
  flex-direction: column;
  align-items: flex-start;
  overflow: hidden;
  padding: 18px 18px 14px 22px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.94), rgba(16, 19, 23, 0.98));
  color: #c5c8c0;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(20px);
  transition: all 0.3s var(--ease-spring);
}
.notebook-card:hover {
  transform: translateY(-4px);
  border-color: rgba(195, 239, 131, 0.4);
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.5), 0 0 30px rgba(195, 239, 131, 0.1), inset 0 0 0 1px rgba(195, 239, 131, 0.08);
}
.notebook-accent {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 4px;
  background: var(--dash-lime);
  box-shadow: 0 0 10px rgba(195, 239, 131, 0.5);
}
.notebook-accent.coral {
  background: var(--dash-coral);
  box-shadow: 0 0 10px rgba(244, 125, 105, 0.5);
}
.notebook-symbol {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  margin-bottom: 12px;
  border-radius: 11px;
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
  font-size: 19px;
  font-weight: 700;
  border: 1px solid rgba(195, 239, 131, 0.2);
  transition: transform 0.25s var(--ease-spring);
}
