  position: relative;
  flex: 1;
  height: 3px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}
.loader-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #c3ef83, #86c5ed);
  transition: width 0.15s ease-out;
  position: relative;
}
.loader-progress-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
  animation: loaderProgressShimmer 1.5s ease-in-out infinite;
}
.loader-progress-glow {
  position: absolute;
  top: 50%;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: rgba(195, 239, 131, 0.6);
  filter: blur(8px);
  transform: translate(-50%, -50%);
  transition: left 0.15s ease-out;
  pointer-events: none;
}
.loader-progress-text {
  color: rgba(195, 239, 131, 0.8);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  min-width: 32px;
  text-align: right;
}

/* Status */
.loader-status {
  color: #6b7280;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.3px;
  margin: 0;
  transition: opacity 0.3s;
}

/* Scanline */
.loader-scanline {
  position: absolute;
  left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(195, 239, 131, 0.3), transparent);
  animation: loaderScanline 3s ease-in-out infinite;
  pointer-events: none;
}


/* ═══════════════════════════════════════════════════════
   ENHANCED SCROLL ANIMATIONS & GLOW EFFECTS
   ═══════════════════════════════════════════════════════ */

/* Magnetic cursor glow on feature cards */
.feature-card {
  --glow-x: 50%;
  --glow-y: 50%;
}
.feature-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    400px circle at var(--glow-x) var(--glow-y),
    rgba(195, 239, 131, 0.08),
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
  z-index: 0;
}
.feature-card:hover::after {
  opacity: 1;
}

/* Staggered bento card reveals */
.feature-card {
  transition: all 0.5s var(--ease-spring), opacity 0.7s ease, transform 0.7s var(--ease-spring);
}
.landing.reveal-enabled .feature-card:not(.is-revealed) {
  opacity: 0;
  transform: translateY(40px) scale(0.95);
}
.feature-card.is-revealed {
  opacity: 1 !important;
  transform: translateY(0) scale(1);
  animation: cardReveal 0.8s var(--ease-spring) both;
  animation-delay: calc(var(--card-index, 0) * 0.1s);
}

@keyframes cardReveal {
  0% {
    opacity: 0;
    transform: translateY(40px) scale(0.95) rotateX(4deg);
    filter: blur(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1) rotateX(0);
    filter: blur(0);
  }
}

/* Enhanced section heading reveals */
.section-heading {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.9s ease, transform 0.9s var(--ease-spring);
}
.is-visible .section-heading,
.is-visible.section-heading {
  opacity: 1;
  transform: translateY(0);
}

/* Glowing section divider animation */
.feature-section::before, .learn-mode-section::before, .comparison-section::before {
  animation: sectionGlowPulse 3s ease-in-out infinite;
}
@keyframes sectionGlowPulse {
  0%, 100% { width: 100px; opacity: 0.3; }
  50% { width: 200px; opacity: 0.7; }
}

