@import "tailwindcss";

:root {
  color-scheme: dark;
  --background: #0b0d10;
  --panel: #161a20;
  --panel-soft: #12151a;
  --foreground: #f1f0ec;
  --muted: #8b9098;
  --faint: #5d626a;
  --line: rgba(255, 255, 255, 0.08);
  --lime: #c3ef83;
  --lime-dim: rgba(195, 239, 131, 0.1);
  --lime-glow: rgba(195, 239, 131, 0.25);
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
}

* { box-sizing: border-box; }
html {
  scroll-behavior: smooth;
}
body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--lime); outline-offset: 4px; }
a { color: inherit; text-decoration: none; }

/* ═══════════════════════════════════════════════════════
   ULTRA-SMOOTH ANIMATIONS & KEYFRAMES
   ═══════════════════════════════════════════════════════ */
@keyframes smoothReveal {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.99);
    filter: blur(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes floatSmooth {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  33% { transform: translateY(-6px) rotate(0.3deg); }
  66% { transform: translateY(3px) rotate(-0.2deg); }
}

@keyframes pulseGlow {
  0%, 100% { opacity: 0.08; transform: scale(1); }
  50% { opacity: 0.18; transform: scale(1.05); }
}

@keyframes softPulse {
  0%, 100% { opacity: 0.7; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.04); }
}

@keyframes waveDance {
  0%, 100% { transform: scaleY(0.35); }
  50% { transform: scaleY(1); }
}

@keyframes borderGlowPulse {
  0%, 100% { box-shadow: 0 0 12px rgba(195, 239, 131, 0.12); }
  50% { box-shadow: 0 0 24px rgba(195, 239, 131, 0.28); }
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

@keyframes gradientShift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

@keyframes textGlow {
  0%, 100% { text-shadow: 0 0 16px rgba(195, 239, 131, 0.25); }
  50% { text-shadow: 0 0 32px rgba(195, 239, 131, 0.5), 0 0 48px rgba(195, 239, 131, 0.25); }
}

@keyframes slideUpFade {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes rotateIn {
  from { opacity: 0; transform: rotate(-3deg) scale(0.95); }
  to { opacity: 1; transform: rotate(0) scale(1); }
}

@keyframes floatParticle {
  0%, 100% { transform: translate(0, 0) rotate(0deg); opacity: 0.25; }
  25% { transform: translate(20px, -20px) rotate(90deg); opacity: 0.5; }
  50% { transform: translate(-15px, -40px) rotate(180deg); opacity: 0.35; }
  75% { transform: translate(-25px, -15px) rotate(270deg); opacity: 0.4; }
}

/* New ultra-smooth keyframes */
@keyframes heroGreetingEnter {
  0% {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
    filter: blur(4px);
  }
  60% {
    opacity: 1;
    transform: translateY(-2px) scale(1.01);
    filter: blur(0);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes authPanelEnter {
  0% {
    opacity: 0;
    transform: translateX(30px) scale(0.98);
    filter: blur(6px);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1);
    filter: blur(0);
  }
}

@keyframes authAsideEnter {
  0% {
    opacity: 0;
    transform: translateX(-30px);
    filter: blur(4px);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes inputFocus {
  0% { box-shadow: 0 0 0 0 rgba(195, 239, 131, 0.2); }
  100% { box-shadow: 0 0 0 4px rgba(195, 239, 131, 0); }
}

@keyframes buttonMagnetic {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-1px) scale(1.005); }
}

@keyframes liveDotBreath {
  0%, 100% { opacity: 0.6; transform: scale(1); box-shadow: 0 0 8px rgba(195, 239, 131, 0.4); }
  50% { opacity: 1; transform: scale(1.15); box-shadow: 0 0 20px rgba(195, 239, 131, 0.7), 0 0 30px rgba(195, 239, 131, 0.4); }
}

@keyframes rippleGlow {
  0% { transform: scale(0.8); opacity: 0.5; }
  100% { transform: scale(2.5); opacity: 0; }
}

/* Staggered entrance animations */
.stagger-children > * {
  animation: slideUpFade 0.6s var(--ease-spring) both;
}
.stagger-children > *:nth-child(1) { animation-delay: 0.05s; }
.stagger-children > *:nth-child(2) { animation-delay: 0.1s; }
.stagger-children > *:nth-child(3) { animation-delay: 0.15s; }
.stagger-children > *:nth-child(4) { animation-delay: 0.2s; }
.stagger-children > *:nth-child(5) { animation-delay: 0.25s; }
.stagger-children > *:nth-child(6) { animation-delay: 0.3s; }

/* Keep content visible unless the landing page has initialized its observer. */
.reveal-on-scroll {
  opacity: 0;
  transform: translateY(24px) scale(0.985);
  filter: blur(4px);
  transition: opacity 0.7s var(--ease-spring), transform 0.7s var(--ease-spring), filter 0.7s var(--ease-spring);
}
.reveal-on-scroll.is-visible { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
.reveal-on-scroll.delay-1 { transition-delay: 0.08s; }
.reveal-on-scroll.delay-2 { transition-delay: 0.16s; }
.reveal-on-scroll.delay-3 { transition-delay: 0.24s; }
.reveal-on-scroll.delay-4 { transition-delay: 0.32s; }
.reveal-on-scroll.delay-5 { transition-delay: 0.4s; }

/* Fallback: if JS doesn't run, show everything after 200ms */
.reveal-on-scroll.no-js {
  opacity: 1;
  transform: none;
  filter: none;
  transition: none;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
  .landing.reveal-enabled .reveal-on-scroll:not(.is-visible) {
    opacity: 1;
    transform: none;
    filter: none;

