   email,
   provider,

result.content:
  provider,
}: {
  name: string;
  email: string;
  provider: string;
}) {
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dashboardRef = useRef<HTMLElement>(null);
  const [notebooks, setNotebooks] = useState<Notebook[]>([]);
  const [search, setSearch] = useState("");
  const [prompt, setPrompt] = useState("");
  const [youtubeOpen, setYoutubeOpen] = useState(false);
  const [youtubeUrl, setYoutubeUrl] = useState("");
  const [notice, setNotice] = useState("");
  const [activeNav, setActiveNav] = useState("Home");
  const [profileOpen, setProfileOpen] = useState(false);
  const [isSigningOut, setIsSigningOut] = useState(false);

  useEffect(() => {
    const dashboard = dashboardRef.current;
    if (!dashboard) return;

    const revealElements = dashboard.querySelectorAll<HTMLElement>(".dashboard-reveal");
    const showAll = () => revealElements.forEach((element) => element.classList.add("is-revealed"));

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches || !("IntersectionObserver" in window)) {
      showAll();
      return;
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-revealed");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08, rootMargin: "0px 0px -8% 0px" });

    revealElements.forEach((element) => {
      if (element.getBoundingClientRect().top < window.innerHeight) {
        element.classList.add("is-revealed");
      } else {
        observer.observe(element);
      }
    });
    dashboard.classList.add("reveal-enabled");
    return () => {
      observer.disconnect();
      dashboard.classList.remove("reveal-enabled");
    };
  }, []);

  const visibleNotebooks = useMemo(
    () => notebooks.filter((notebook) =>
      `${notebook.title} ${notebook.subtitle}`.toLowerCase().includes(search.toLowerCase()),
    ),
    [notebooks, search],
  );

  function createSourceNotebook(title: string, subtitle: string) {
    const notebookTitle = title.trim() || "Untitled study source";
    setNotebooks((items) => [
      {
        id: crypto.randomUUID(),
        title: notebookTitle,
        subtitle,
        notes: 1,
        opened: "Added just now",
        symbol: "✳",
        accent: items.length % 2 === 0 ? "teal" : "coral",
      },
      ...items,
    ]);
    setNotice(`Created a demo notebook from “${notebookTitle}”.`);
  }

  function handlePromptSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const title = prompt.trim();
    if (!title) return;
    setNotice("Add a PDF, presentation, or YouTube source to create a notebook from your study material.");
  }

  function addYouTubeSource(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!youtubeUrl.trim()) return;
    if (!/^https?:\/\/(?:www\.)?(?:m\.)?(?:youtube\.com|youtu\.be)\//i.test(youtubeUrl.trim())) {
      setNotice("Enter a valid YouTube video link to create a notebook.");
      return;
    }
    createSourceNotebook("YouTube study source", "YouTube video · Just now");
    setYoutubeUrl("");
    setYoutubeOpen(false);
  }

  async function signOut() {
    setIsSigningOut(true);
    try {
      const { error } = await createClient().auth.signOut();
      if (error) throw error;
      router.replace("/");
      router.refresh();
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not sign out. Please try again.");
      setIsSigningOut(false);
    }
  }

  function chooseNavigation(label: string) {
    setActiveNav(label);
    if (label === "Home") {
      window.scrollTo({ top: 0, behavior: "smooth" });
      return;
    }
    if (label === "Notebooks") {
      document.getElementById("notebooks")?.scrollIntoView({ behavior: "smooth" });
      return;
    }
    setNotice(`${label} is part of your Synapse workspace. This module is coming soon.`);
  }

  return (
    <main className="dashboard-shell" ref={dashboardRef}>
      <aside className="dashboard-sidebar">
        <a className="dashboard-brand" href="/dashboard" aria-label="Synapse home">
          <span className="dashboard-brand-mark"><Icon name="spark" size={22} /></span>
          <span>synapse<span>.</span></span>
        </a>

        <div className="sidebar-label">WORKSPACE</div>
        <nav className="sidebar-nav" aria-label="Workspace navigation">
          {navigation.map((item) => (
            <button
              className={`sidebar-link${activeNav === item.label ? " active" : ""}`}
              type="button"
              key={item.label}
              onClick={() => chooseNavigation(item.label)}
            >
              <Icon name={item.icon} size={19} />
              <span>{item.label}</span>
              {item.label === "Chat" && <span className="nav-new">AI</span>}
            </button>
          ))}
        </nav>

        <div className="sidebar-spacer" />
        <div className="sidebar-note">
          <span className="sidebar-note-icon"><Icon name="spark" size={16} /></span>
          <p>Small steps.<br /><b>Big dreams.</b></p>
          <span className="sidebar-note-spark">✳</span>
        </div>
        <div className="sidebar-footer">
          <span className="open-source-mark">✳</span>
          <span><b>Open source</b><small>Built by learners, for learners.</small></span>
          <span className="coral-heart">♥</span>
        </div>
      </aside>

      <div className="dashboard-main">
        <header className="dashboard-topbar">
          <div className="topbar-crumb"><span className="crumb-home"><Icon name="home" size={15} /></span><span>Home</span></div>
          <div className="topbar-actions">
            <ThemeToggle />
            <span className="account-provider"><span className="account-dot" /> {provider} account</span>
            <div className="profile-wrap">
              <button
                type="button"
                className="profile-button"
                aria-label="Open account menu"
                aria-expanded={profileOpen}
                onClick={() => setProfileOpen((open) => !open)}
              >
                <span className="profile-avatar">{name.charAt(0).toUpperCase()}</span>
                <span className="profile-name">{name}</span>
                <Icon name="chevron" size={15} />
              </button>
              {profileOpen && (
                <div className="profile-menu">
                  <b>{name}</b>
                  <span>{email}</span>
                  <button type="button" onClick={signOut} disabled={isSigningOut}>
                    <Icon name="logout" size={15} /> {isSigningOut ? "Signing out…" : "Sign out"}
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="dashboard-content">
          <section className="dashboard-welcome dashboard-reveal">
            <div className="welcome-copy">
              <span className="dashboard-eyebrow"><span /> YOUR STUDY SPACE, IN SYNC</span>
              <h1>What do you want<br className="welcome-break" /> to learn<span>?</span></h1>
              <p>Bring your class materials into one calm workspace. Your next little win starts here.</p>
            </div>
            <div className="welcome-art-wrap">
              <div className="welcome-art-orbit orbit-a" />
              <div className="welcome-art-orbit orbit-b" />
              <StudyIllustration />
              <div className="welcome-speech">Let&apos;s learn!</div>
            </div>
            <div className="encouragement-card">
              <span className="encouragement-icon"><Icon name="spark" size={18} /></span>
              <span><b>Keep going, {name}.</b><small>Small steps. Big dreams.</small></span>
              <span className="encouragement-bars"><i /><i /><i /></span>
            </div>
          </section>

          <section className="study-prompt-card dashboard-reveal" aria-label="Start learning">
            <div className="prompt-tip"><Icon name="spark" size={16} /><span>Add a PDF, presentation, or YouTube link to create your first notebook</span></div>
            <form className="prompt-form" onSubmit={handlePromptSubmit}>
              <input
                aria-label="What would you like to learn"
                value={prompt}
                onChange={(event) => setPrompt(event.target.value)}
                placeholder="What would you like to learn from your materials?"
              />
              <button className="prompt-submit" type="submit" aria-label="Start learning" disabled={!prompt.trim()}>
                <Icon name="arrow" size={20} />
              </button>
            </form>
            <div className="prompt-actions">
              <button className="source-action record-action" type="button" onClick={() => setNotice("Live recording is coming soon. You can upload a lecture file for now.")}><Icon name="mic" size={16} /> Record</button>
              <button className="source-action" type="button" onClick={() => fileInputRef.current?.click()}><Icon name="upload" size={16} /> Upload</button>
              <input
                ref={fileInputRef}
                className="sr-only"
                type="file"
                accept=".pdf,.ppt,.pptx,.doc,.docx,.txt"
                onChange={(event) => {
                  const file = event.currentTarget.files?.[0];
                  if (file) {
                    const title = file.name.replace(/\.[^.]+$/, "");
                    const fileType = file.name.split(".").pop()?.toUpperCase() ?? "FILE";
                    createSourceNotebook(title, `${fileType} source · Just now`);
                  }
                  event.currentTarget.value = "";
                }}
              />
              <button className={`source-action${youtubeOpen ? " selected" : ""}`} type="button" onClick={() => setYoutubeOpen((open) => !open)}><Icon name="youtube" size={16} /> YouTube</button>
              <span className="prompt-hint">PDF, slides, notes & more</span>
            </div>
            {youtubeOpen && (
              <form className="youtube-form" onSubmit={addYouTubeSource}>
                <input type="url" aria-label="YouTube video URL" placeholder="Paste a YouTube video link" value={youtubeUrl} onChange={(event) => setYoutubeUrl(event.target.value)} required />
                <button type="submit">Add link <Icon name="arrow" size={15} /></button>
              </form>
            )}
          </section>

          <section className="notebooks-section dashboard-reveal" id="notebooks">
            <div className="notebooks-heading">
              <div className="notebooks-title"><span className="notebooks-title-icon"><Icon name="book" size={22} /></span><div><h2>Your notebooks</h2><p>Upload a source to build your first study notebook.</p></div></div>
              <div className="notebook-tools">
                <label className="notebook-search"><Icon name="search" size={17} /><input aria-label="Search notebooks" placeholder="Search notebooks..." value={search} onChange={(event) => setSearch(event.target.value)} />{search && <button type="button" onClick={() => setSearch("")} aria-label="Clear search"><Icon name="close" size={15} /></button>}</label>
                <button className="new-notebook-button" type="button" onClick={() => fileInputRef.current?.click()}><Icon name="upload" size={17} /> Add a source</button>
              </div>
            </div>
            {visibleNotebooks.length ? (
              <div className="notebooks-grid">
                {visibleNotebooks.map((notebook) => <NotebookCard key={notebook.id} notebook={notebook} onOpen={() => setNotice(`${notebook.title} notebook opened in preview mode.`)} />)}
              </div>
            ) : (
              <div className="notebooks-empty">
                <div className="empty-mascot-icon">
                  <Icon name={notebooks.length ? "search" : "upload"} size={30} />
                </div>
                <b>{notebooks.length ? "No notebooks match your search" : "Your study space is ready"}</b>
                <span>
                  {notebooks.length
                    ? "Try another search, or clear the search field to see your sources."
                    : "You haven't created any notebooks yet. Upload a lecture PDF or slides presentation, or paste a YouTube video to build your first study notebook."}
                </span>
                {!notebooks.length && (
                  <div className="empty-actions">
                    <button
                      className="empty-source-button"
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                    >
                      <Icon name="upload" size={15} /> Upload PDF or Slides
                    </button>
                    <button
                      className="empty-source-button empty-source-button-alt"
                      type="button"
                      onClick={() => {
                        setYoutubeOpen(true);
                        window.scrollTo({ top: 300, behavior: "smooth" });
                      }}
                    >
                      <Icon name="youtube" size={15} /> Paste YouTube Video
                    </button>
                  </div>
                )}
              </div>
            )}
          </section>

          {notice && (
            <div className="dashboard-toast" role="status">
              <Icon name="spark" size={16} /><span>{notice}</span><button type="button" aria-label="Dismiss message" onClick={() => setNotice("")}><Icon name="close" size={16} /></button>
            </div>
          )}
        </div>
      </div>
    </main>
  );
}

