                   if (file) {
                     const title = file.name.replace(/\.[^.]+$/, "");
                     const fileType = file.name.split(".").pop()?.toUpperCase() ?? "FILE";
                     createSourceNotebook(title, `${fileType} source · Just now`);
                   }
                   event.currentTarget.value = "";
                 }}
               />
               <button className={`source-action${youtubeOpen ? " selected" : ""}`} type="button" onClick={() => setYoutubeOpen((open) => !open)}><Icon name="youtube" size={16} /> YouTube</button>
               <span className="prompt-hint">PDF, slides, notes & more</span>
             </div>
             {youtubeOpen && (
               <form className="youtube-form" onSubmit={addYouTubeSource}>
                 <input type="url" aria-label="YouTube video URL" placeholder="Paste a YouTube video link" value={youtubeUrl} onChange={(event) => setYoutubeUrl(event.target.value)} required />
                 <button type="submit">Add link <Icon name="arrow" size={15} /></button>
               </form>
             )}
           </section>

           <section className="notebooks-section dashboard-reveal" id="notebooks">
             <div className="notebooks-heading">
               <div className="notebooks-title"><span className="notebooks-title-icon"><Icon name="book" size={22} /></span><div><h2>Your notebooks</h2><p>Upload a source to build your first study notebook.</p></div></div>
               <div className="notebook-tools">
                 <label className="notebook-search"><Icon name="search" size={17} /><input aria-label="Search notebooks" placeholder="Search notebooks..." value={search} onChange={(event) => setSearch(event.target.value)} />{search && <button type="button" onClick={() => setSearch("")} aria-label="Clear search"><Icon name="close" size={15} /></button>}</label>
                 <button className="new-notebook-button" type="button" onClick={() => fileInputRef.current?.click()}><Icon name="upload" size={17} /> Add a source</button>
               </div>
             </div>
             {visibleNotebooks.length ? (
               <div className="notebooks-grid">
                 {visibleNotebooks.map((notebook) => <NotebookCard key={notebook.id} notebook={notebook} onOpen={() => setNotice(`${notebook.title} notebook opened in preview mode.`)} />)}
               </div>
             ) : (
               <div className="notebooks-empty">
                 <div className="empty-mascot-icon">
                   <Icon name={notebooks.length ? "search" : "upload"} size={30} />
                 </div>
                 <b>{notebooks.length ? "No notebooks match your search" : "Your study space is ready"}</b>
                 <span>
                   {notebooks.length
                     ? "Try another search, or clear the search field to see your sources."
                     : "You haven't created any notebooks yet. Upload a lecture PDF or slides presentation, or paste a YouTube video to build your first study notebook."}
                 </span>
                 {!notebooks.length && (
                   <div className="empty-actions">
                     <button
                       className="empty-source-button"
                       type="button"
                       onClick={() => fileInputRef.current?.click()}
                     >
                       <Icon name="upload" size={15} /> Upload PDF or Slides
                     </button>
                     <button
                       className="empty-source-button empty-source-button-alt"
                       type="button"
                       onClick={() => {
                         setYoutubeOpen(true);
                         window.scrollTo({ top: 300, behavior: "smooth" });
                       }}
                     >
                       <Icon name="youtube" size={15} /> Paste YouTube Video
                     </button>
                   </div>
                 )}
               </div>
             )}
           </section>

           {notice && (
             <div className="dashboard-toast" role="status">
               <Icon name="spark" size={16} /><span>{notice}</span><button type="button" aria-label="Dismiss message" onClick={() => setNotice("")}><Icon name="close" size={16} /></button>
             </div>
           )}
         </div>
       </div>
     </main>
   );
 }

