function ProfileAvatar({ name, avatarUrl, size = 32 }: { name: string; avatarUrl?: string; size?: number }) {
  const initials = name
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  if (avatarUrl) {
    return (
      <img
        src={avatarUrl}
        alt=""
        className="profile-avatar-img"
        width={size}
        height={size}
        style={{ borderRadius: "50%", objectFit: "cover" }}
      />
    );
  }

  return (
    <span className="profile-avatar-fallback" style={{ width: size, height: size, fontSize: size * 0.35 }}>
      {initials}
    </span>
  );
}

export default function DashboardHome({
  name,
  email,
  provider,
  avatarUrl,
}: {
  name: string;
  email: string;
  provider: string;
  avatarUrl?: string;
}) {
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dashboardRef = useRef<HTMLElement>(null);
  const sidebarRef = useRef<HTMLElement>(null);
  const [notebooks, setNotebooks] = useState<Notebook[]>([]);
  const [search, setSearch] = useState("");
  const [prompt, setPrompt] = useState("");
  const [youtubeOpen, setYoutubeOpen] = useState(false);
  const [youtubeUrl, setYoutubeUrl] = useState("");
  const [notice, setNotice] = useState("");
  const [activeNav, setActiveNav] = useState("Home");
  const [profileOpen, setProfileOpen] = useState(false);
  const [isSigningOut, setIsSigningOut] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  useEffect(() => {
    const dashboard = dashboardRef.current;
    if (!dashboard) return;

    const revealElements = dashboard.querySelectorAll<HTMLElement>(".dashboard-reveal");
    const showAll = () => revealElements.forEach((element) => element.classList.add("is-revealed"));

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches || !("IntersectionObserver" in window)) {
      showAll();
      return;
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-revealed");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08, rootMargin: "0px 0px -8% 0px" });

    revealElements.forEach((element) => {
      if (element.getBoundingClientRect().top < window.innerHeight) {
        element.classList.add("is-revealed");
      } else {
        observer.observe(element);
      }
    });
    dashboard.classList.add("reveal-enabled");
    return () => {
      observer.disconnect();
      dashboard.classList.remove("reveal-enabled");
    };
  }, []);

  const visibleNotebooks = useMemo(
    () => notebooks.filter((notebook) =>
      `${notebook.title} ${notebook.subtitle}`.toLowerCase().includes(search.toLowerCase()),
    ),
    [notebooks, search],
  );

  function createSourceNotebook(title: string, subtitle: string) {
    const notebookTitle = title.trim() || "Untitled study source";
    setNotebooks((items) => [
      {
        id: crypto.randomUUID(),
        title: notebookTitle,
        subtitle,
        notes: 1,
        opened: "Added just now",
        symbol: "✳",
        accent: items.length % 2 === 0 ? "teal" : "coral",
      },
      ...items,
    ]);
    setNotice(`Created a demo notebook from “${notebookTitle}”.`);
  }

  function handlePromptSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const title = prompt.trim();
    if (!title) return;
    setNotice("Add a PDF, presentation, or YouTube source to create a notebook from your study material.");
  }

  function addYouTubeSource(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!youtubeUrl.trim()) return;
    if (!/^https?:\/\/(?:www\.)?(?:m\.)?(?:youtube\.com|youtu\.be)\//i.test(youtubeUrl.trim())) {
      setNotice("Enter a valid YouTube video link to create a notebook.");
      return;
    }
    createSourceNotebook("YouTube study source", "YouTube video · Just now");
    setYoutubeUrl("");
    setYoutubeOpen(false);
  }

  async function signOut() {
    setIsSigningOut(true);
    try {
      const { error } = await createClient().auth.signOut();
      if (error) throw error;
