export default function DashboardHome({
  name,
  email,
  provider,
  avatarUrl,
}: {
  name: string;
  email: string;
  provider: string;
  avatarUrl?: string;
}) {
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dashboardRef = useRef<HTMLElement>(null);
  const sidebarRef = useRef<HTMLElement>(null);
  const [notebooks, setNotebooks] = useState<Notebook[]>([]);
  const [selectedNotebook, setSelectedNotebook] = useState<Notebook | null>(null);
  const [chatMessages, setChatMessages] = useState<StudyMessage[]>([]);
  const [chatPrompt, setChatPrompt] = useState("");
  const [isLoadingNotebooks, setIsLoadingNotebooks] = useState(true);
  const [isIngesting, setIsIngesting] = useState(false);
  const [isSendingMessage, setIsSendingMessage] = useState(false);
  const [search, setSearch] = useState("");
  const [prompt, setPrompt] = useState("");
  const [youtubeOpen, setYoutubeOpen] = useState(false);
  const [youtubeUrl, setYoutubeUrl] = useState("");
  const [notice, setNotice] = useState("");
  const [activeNav, setActiveNav] = useState("Home");
  const [profileOpen, setProfileOpen] = useState(false);
  const [isSigningOut, setIsSigningOut] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  useEffect(() => {
    let isMounted = true;
    async function loadNotebooks() {
      const { data, error } = await createClient()
        .from("study_notebooks")
        .select("id, title, source_name, source_type, content, created_at")
        .order("created_at", { ascending: false });

      if (!isMounted) return;
      if (error) {
        setNotice("Could not load notebooks. Run the Synapse database migration in Supabase.");
      } else {
        setNotebooks((data ?? []).map((row, index) => ({
          id: row.id,
          title: row.title,
          subtitle: `${row.source_name} · ${row.source_type.toUpperCase()}`,
          content: row.content,
          notes: 1,
          opened: new Date(row.created_at).toLocaleDateString(),
          symbol: "✳",
          accent: index % 2 === 0 ? "teal" : "coral",
        })));
      }
      setIsLoadingNotebooks(false);
    }

    void loadNotebooks();
    return () => { isMounted = false; };
  }, []);

  useEffect(() => {
    const dashboard = dashboardRef.current;
    if (!dashboard) return;

    const revealElements = dashboard.querySelectorAll<HTMLElement>(".dashboard-reveal");
    const showAll = () => revealElements.forEach((element) => element.classList.add("is-revealed"));

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches || !("IntersectionObserver" in window)) {
      showAll();
      return;
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-revealed");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08, rootMargin: "0px 0px -8% 0px" });

    revealElements.forEach((element) => {
      if (element.getBoundingClientRect().top < window.innerHeight) {
        element.classList.add("is-revealed");
      } else {
        observer.observe(element);
      }
    });
    dashboard.classList.add("reveal-enabled");
    return () => {
      observer.disconnect();
      dashboard.classList.remove("reveal-enabled");
    };
  }, []);

  const visibleNotebooks = useMemo(
    () => notebooks.filter((notebook) =>
      `${notebook.title} ${notebook.subtitle}`.toLowerCase().includes(search.toLowerCase()),
    ),
    [notebooks, search],
  );

  async function addStudyFile(file: File) {
    setIsIngesting(true);
    setNotice(`Reading ${file.name}…`);
    try {
      const formData = new FormData();
      formData.append("file", file);
      const response = await fetch("/api/study/ingest", { method: "POST", body: formData });
      const result = await response.json() as {
        error?: string;
        content?: string;
        sourceName?: string;
        sourceType?: string;
        truncated?: boolean;
      };
      if (!response.ok) throw new Error(result.error || "Could not read this file.");
      if (!result.content || !result.sourceName || !result.sourceType) {
        throw new Error("The source parser returned incomplete data.");
      }

      const title = result.sourceName.replace(/\.[^.]+$/, "").trim().slice(0, 160) || "Untitled study source";
      const { data, error } = await createClient()
        .from("study_notebooks")
        .insert({
          title,
          source_name: result.sourceName,
          source_type: result.sourceType,
          content: result.content,
        })
        .select("id, title, source_name, source_type, content, created_at")
        .single();
      if (error) throw new Error("Could not save the notebook. Run the Synapse database migration in Supabase.");

      const notebook: Notebook = {
        id: data.id,
        title: data.title,
        subtitle: `${data.source_name} · ${data.source_type.toUpperCase()}`,
        content: data.content,
        notes: 1,
        opened: new Date(data.created_at).toLocaleDateString(),
        symbol: "✳",
        accent: notebooks.length % 2 === 0 ? "teal" : "coral",
      };
      setNotebooks((items) => [notebook, ...items]);
      setNotice(result.truncated
        ? "Notebook created. The source text was shortened to fit the current storage limit."
        : `Created “${title}” and extracted its study material.`);
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not process this study source.");
    } finally {
      setIsIngesting(false);
    }
  }

  async function openNotebook(notebook: Notebook) {
    setSelectedNotebook(notebook);
    setChatMessages([]);
    const { data, error } = await createClient()
      .from("study_messages")
      .select("id, role, content")
      .eq("notebook_id", notebook.id)
      .order("created_at", { ascending: true });
    if (error) {
      setNotice("Could not load this notebook's chat. Check the Supabase migration.");
      return;
    }
    setChatMessages((data ?? []).map((row) => ({
      id: row.id,
      role: row.role as "user" | "assistant",
      content: row.content,
    })));
  }

  async function sendChatMessage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const message = chatPrompt.trim();
    if (!message || !selectedNotebook || isSendingMessage) return;

    setChatPrompt("");
    setIsSendingMessage(true);
    const optimisticMessage: StudyMessage = { id: crypto.randomUUID(), role: "user", content: message };
    setChatMessages((items) => [...items, optimisticMessage]);
    try {
      const response = await fetch("/api/study/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notebookId: selectedNotebook.id, message }),
      });
      const result = await response.json() as { answer?: string; error?: string };
      if (!response.ok) throw new Error(result.error || "Could not get an answer.");
      if (!result.answer) throw new Error("The AI returned an empty response.");
      setChatMessages((items) => [
        ...items,
        { id: crypto.randomUUID(), role: "assistant", content: result.answer! },
      ]);
    } catch (error) {
      setChatMessages((items) => items.filter((item) => item.id !== optimisticMessage.id));
      setChatPrompt(message);
      setNotice(error instanceof Error ? error.message : "Could not send your message.");
    } finally {
      setIsSendingMessage(false);
    }
  }

  function handlePromptSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const title = prompt.trim();
    if (!title) return;
    setNotice("Add a PDF, presentation, or YouTube source to create a notebook from your study material.");
  }

  function addYouTubeSource(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!youtubeUrl.trim()) return;
    if (!/^https?:\/\/(?:www\.)?(?:m\.)?(?:youtube\.com|youtu\.be)\//i.test(youtubeUrl.trim())) {
      setNotice("Enter a valid YouTube video link to create a notebook.");
      return;
    }
    setNotice("YouTube links cannot be transcribed directly yet. Upload the video/audio file, or save its transcript as a .txt file and upload that.");
  }

  async function signOut() {
    setIsSigningOut(true);
    try {
      const { error } = await createClient().auth.signOut();
      if (error) throw error;
      router.replace("/");
      router.refresh();
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "Could not sign out. Please try again.");
      setIsSigningOut(false);
    }
  }

  function chooseNavigation(label: string) {
