import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { isSupabaseConfigured } from "@/lib/supabase/config";
import { groqChatCompletion } from "@/lib/study/groq";

const MAX_MESSAGE_LENGTH = 4000;
const MAX_CONTEXT_LENGTH = 60_000;

function jsonError(message: string, status: number) {
  return NextResponse.json({ error: message }, { status });
}

export async function POST(request: Request) {
  if (!isSupabaseConfigured()) return jsonError("Supabase is not configured for this app.", 503);

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return jsonError("Send a valid chat message.", 400);
  }

  if (!body || typeof body !== "object") return jsonError("Send a valid chat message.", 400);
  const { notebookId, message } = body as { notebookId?: unknown; message?: unknown };
  if (typeof notebookId !== "string" || !/^[0-9a-f-]{36}$/i.test(notebookId)) {
    return jsonError("Choose a valid notebook before chatting.", 400);
  }
  if (typeof message !== "string" || !message.trim() || message.length > MAX_MESSAGE_LENGTH) {
    return jsonError(`Messages must be between 1 and ${MAX_MESSAGE_LENGTH} characters.`, 400);
  }

  let supabase;
  try {
    supabase = await createClient();
  } catch (error) {
    console.error("Could not initialize Supabase for study chat", error);
    return jsonError("Could not verify your session. Check the Supabase configuration.", 503);
  }

  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) return jsonError("Sign in to chat with your study materials.", 401);

  const { data: notebook, error: notebookError } = await supabase
    .from("study_notebooks")
    .select("id, title, content")
    .eq("id", notebookId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (notebookError) {
    console.error("Could not load study notebook", notebookError);
    return jsonError("Could not load this notebook. Verify that the Synapse database migration is installed.", 503);
  }
  if (!notebook) return jsonError("Notebook not found.", 404);

  const { data: previousMessages, error: messagesError } = await supabase
    .from("study_messages")
    .select("role, content")
    .eq("notebook_id", notebook.id)
    .eq("user_id", user.id)
    .order("created_at", { ascending: false })
    .limit(10);

  if (messagesError) {
    console.error("Could not load previous study messages", messagesError);
    return jsonError("Could not load notebook chat. Verify that the Synapse database migration is installed.", 503);
  }

  let answer: string;
  try {
    answer = await groqChatCompletion([
      {
        role: "system",
        content: `You are Synapse, a careful study assistant. Answer using the student's source material when relevant. If the source does not contain the answer, say so and distinguish general knowledge from source-based information. Explain concepts clearly and encourage learning rather than giving unsupported claims.\n\nNotebook: ${notebook.title}\n\nSource material:\n${notebook.content.slice(0, MAX_CONTEXT_LENGTH)}`,
      },
      ...(previousMessages ?? []).reverse().map((item) => ({
        role: item.role as "user" | "assistant",
        content: item.content,
      })),
      { role: "user", content: message.trim() },
    ]);
  } catch (error) {
    const messageText = error instanceof Error ? error.message : "The AI request failed.";
    return jsonError(messageText, messageText.includes("not configured") ? 503 : 502);
  }

  const { error: saveError } = await supabase.from("study_messages").insert([
    { notebook_id: notebook.id, user_id: user.id, role: "user", content: message.trim() },
    { notebook_id: notebook.id, user_id: user.id, role: "assistant", content: answer },
  ]);

  if (saveError) {
    console.error("Could not save study chat messages", saveError);
    return jsonError("The answer was generated, but the conversation could not be saved.", 503);
  }

  return NextResponse.json({ answer });
}

create table if not exists public.study_notebooks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 160),
  source_name text not null check (char_length(source_name) between 1 and 200),
  source_type text not null check (source_type in ('pdf', 'pptx', 'docx', 'text', 'audio', 'video')),
  content text not null check (char_length(content) between 1 and 90000),
  created_at timestamptz not null default now()
);

create index if not exists study_notebooks_user_created_idx
  on public.study_notebooks (user_id, created_at desc);

alter table public.study_notebooks enable row level security;

create policy "Users can read their own study notebooks"
  on public.study_notebooks for select
  using ((select auth.uid()) = user_id);

create policy "Users can create their own study notebooks"
  on public.study_notebooks for insert
  with check ((select auth.uid()) = user_id);

create policy "Users can delete their own study notebooks"
  on public.study_notebooks for delete
  using ((select auth.uid()) = user_id);

create table if not exists public.study_messages (
  id uuid primary key default gen_random_uuid(),
  notebook_id uuid not null references public.study_notebooks (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  role text not null check (role in ('user', 'assistant')),
  content text not null check (char_length(content) between 1 and 12000),
  created_at timestamptz not null default now()
);

create index if not exists study_messages_notebook_created_idx
  on public.study_messages (notebook_id, created_at);

alter table public.study_messages enable row level security;

create policy "Users can read messages in their own notebooks"
  on public.study_messages for select
  using (
    (select auth.uid()) = user_id
    and exists (
      select 1 from public.study_notebooks
      where study_notebooks.id = study_messages.notebook_id
        and study_notebooks.user_id = (select auth.uid())
    )
  );

create policy "Users can create messages in their own notebooks"
  on public.study_messages for insert
  with check (
    (select auth.uid()) = user_id
    and exists (
      select 1 from public.study_notebooks
      where study_notebooks.id = study_messages.notebook_id
        and study_notebooks.user_id = (select auth.uid())
    )
  );

import { NextResponse, type NextRequest } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { isSupabaseConfigured } from "@/lib/supabase/config";

function redirectWithAuthError(request: NextRequest, code: string, message?: string) {
  const destination = new URL("/", request.url);
  destination.searchParams.set("authError", code);

  if (message) {
    destination.searchParams.set("authMessage", message.slice(0, 240));
  }

  return NextResponse.redirect(destination);
}

export async function GET(request: NextRequest) {
  const { searchParams } = request.nextUrl;
  const origin = request.nextUrl.origin;
  const providerError = searchParams.get("error");

  if (providerError) {
    const description = searchParams.get("error_description");
    const message = description
      ? `${providerError}: ${description}`
      : `Google sign-in returned "${providerError}".`;
    return redirectWithAuthError(request, "provider", message);
  }

  if (!isSupabaseConfigured()) {
    return redirectWithAuthError(
      request,
      "configuration",
      "Supabase environment variables are missing. Check NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY.",
    );
  }

  const code = searchParams.get("code");
  if (!code) {
    return redirectWithAuthError(
      request,
      "missing_code",
      "Supabase returned to the app without an authorization code. Check the Google OAuth callback URL and Supabase redirect URL allowlist.",
    );
  }

  const supabase = await createClient();
  const { error } = await supabase.auth.exchangeCodeForSession(code);

  if (error) {
    console.error("Supabase OAuth code exchange failed", {
      code: error.code,
      status: error.status,
      message: error.message,
    });
    return redirectWithAuthError(request, "exchange", error.message);
  }

  const requestedPath = searchParams.get("next");
  const next =
    requestedPath && requestedPath.startsWith("/") && !requestedPath.startsWith("//")
      ? requestedPath
      : "/dashboard";
  const destination = new URL(next, origin);

  if (destination.origin !== origin) {
    return NextResponse.redirect(new URL("/dashboard", origin));
  }

  return NextResponse.redirect(destination);
}

