        }
        if (!quizzesResult.error && quizzesResult.data) {
          setQuizAttempts(quizzesResult.data as QuizAttempt[]);
        }
      } catch (err) {
        console.warn("Could not load decks/quizzes from Supabase:", err);
      }

      setIsLoadingNotebooks(false);
    }

