  border: 1.5px solid rgba(195, 239, 131, 0.6);
  border-right-color: rgba(195, 239, 131, 0.15);
  border-bottom-color: rgba(195, 239, 131, 0.25);
  border-radius: 50%;
  box-shadow: 
    0 0 18px rgba(195, 239, 131, 0.1),
    inset 0 0 20px rgba(195, 239, 131, 0.05);
  animation: borderGlowPulse 3s ease-in-out infinite;
}
.timer-ring span { color: #e9eee1; font-size: 17px; font-variant-numeric: tabular-nums; font-weight: 700; letter-spacing: -0.6px; }
.timer-ring small { margin-top: 2px; color: #a4b494; font-size: 7px; letter-spacing: 1.2px; font-weight: 600; }
.focus-info b { color: #e4e7df; font-size: 12px; font-weight: 600; }
.focus-info span { color: #81878a; font-size: 9px; }
.focus-progress { height: 3px; overflow: hidden; border-radius: 4px; background: rgba(255, 255, 255, 0.08); }
.focus-progress span {
  display: block;
  width: 63%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #9bbd6a, var(--lime));
  box-shadow: 0 0 10px rgba(195, 239, 131, 0.4);
  animation: progressFill 2s ease-out;
}
@keyframes progressFill {
  from { width: 0%; }
  to { width: 63%; }
}
.preview-bottom {
  display: grid;
  grid-template-columns: 1.35fr 0.8fr;
  gap: 9px;
  margin-top: 10px;
}
.mini-task, .mini-streak {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
  transition: all 0.3s var(--ease-spring);
}
.mini-task:hover, .mini-streak:hover {
  border-color: rgba(195, 239, 131, 0.3);
  background: rgba(195, 239, 131, 0.03);
  transform: translateY(-2px);
}
.mini-card-icon {
  display: grid;
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 7px;
}
.mint { color: var(--lime); background: rgba(195, 239, 131, 0.12); }
.mini-streak > span { font-size: 16px; color: var(--lime); }

.float-chip {
  position: absolute;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 13px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 8px;
  background: rgba(20, 24, 29, 0.92);
  color: #c5c8c0;
  font-size: 10px;
  font-weight: 550;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(8px);
  animation: floatSmooth 4s ease-in-out infinite;
}
.chip-ai { top: 69px; left: 2px; transform: rotate(-4deg); animation-delay: 0s; }
.chip-ai > span { color: var(--lime); }
.chip-focus { right: -4px; bottom: 76px; transform: rotate(3deg); animation-delay: -2s; }
.chip-focus b { margin-left: 4px; color: #ffffff; }
.chip-pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 10px rgba(195, 239, 131, 0.7);
  animation: softPulse 1.5s ease-in-out infinite;
}

/* SECTION STRUCTURE */
.feature-section, .learn-mode-section, .comparison-section {
  width: min(1192px, calc(100% - 96px));
  margin: 0 auto;
  padding: 76px 0 96px;
  border-top: 1px solid var(--line);
  position: relative;
}
.feature-section::before, .learn-mode-section::before, .comparison-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--lime), transparent);
  opacity: 0.5;
}
.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 34px;
}
.section-heading h2 {
  margin: 13px 0 0;
  color: #edeee8;
  font-size: 36px;
  font-weight: 550;
  letter-spacing: -1.7px;
  line-height: 1.12;
}
.section-heading > p {
  width: 340px;
  margin: 0 0 4px;
  color: #8c9194;
  font-size: 12px;
  line-height: 1.8;
}

/* BENTO GRID */
.bento-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 280px 286px;
  gap: 14px;
}
.feature-card {
  position: relative;
  overflow: hidden;
  padding: 18px 18px 15px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.94), rgba(16, 19, 23, 0.98));
  transition: all 0.3s var(--ease-spring);
  backdrop-filter: blur(20px);
}
.feature-card:hover {
  transform: translateY(-4px);
  border-color: rgba(195, 239, 131, 0.4);
  box-shadow: 
    0 16px 36px rgba(0, 0, 0, 0.4), 
    0 0 25px rgba(195, 239, 131, 0.08),
    0 0 0 1px rgba(195, 239, 131, 0.1) inset;
}
.feature-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(195, 239, 131, 0.03), transparent 60%);
  opacity: 0;
  transition: opacity 0.3s var(--ease-spring);
  pointer-events: none;
}
.feature-card:hover::before {
  opacity: 1;
}
.flash-card { grid-column: 1; grid-row: 1; }
.quiz-card { grid-column: 2; grid-row: 1; }
.audio-card { grid-column: 3; grid-row: 1; }
.mindmap-card { grid-column: 1 / 3; grid-row: 2; }
.planner-card { grid-column: 3; grid-row: 2; }

.card-topline {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.feature-icon {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  transition: transform 0.25s var(--ease-spring), box-shadow 0.25s var(--ease-spring);
}
.feature-card:hover .feature-icon {
  transform: scale(1.1);
  box-shadow: 0 0 20px rgba(195, 239, 131, 0.3);
}
.lime-icon { color: var(--lime); background: rgba(195, 239, 131, 0.1); }
.card-number { color: #71777b; font-size: 8px; letter-spacing: 1.2px; font-weight: 600; }

.feature-copy {
  position: absolute;
  z-index: 2;
  right: 18px;
  bottom: 16px;
  left: 18px;
}
.feature-copy h3 {
  margin: 0 0 5px;
  color: #e9eae5;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.2px;
}
.feature-copy p { margin: 0; color: #858b8e; font-size: 10px; line-height: 1.55; }

/* 3D REAL FLASHCARD FLIP MECHANICS */
.flash-visual {
  position: absolute;
  top: 53px;
  right: 18px;
  left: 18px;
  height: 140px;
  display: grid;
  place-items: center;
  perspective: 1000px;
}
.flashcard-3d-wrapper {
  width: 88%;
  height: 118px;
  cursor: pointer;
  position: relative;
}
.flashcard-3d-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: left;
  transition: transform 0.65s var(--ease-spring);
  transform-style: preserve-3d;
}
.flashcard-3d-inner.is-flipped {
  transform: rotateY(180deg);
}
.flashcard-face {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  border: 1px solid rgba(195, 239, 131, 0.28);
  border-radius: 10px;
  background: linear-gradient(135deg, #1c221b 0%, #121617 100%);
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-shadow: 
    0 14px 28px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(195, 239, 131, 0.05) inset;
}
.flashcard-face-back {
  transform: rotateY(180deg);
  background: linear-gradient(135deg, #182218 0%, #0e1411 100%);
  border-color: var(--lime);
  box-shadow: 
    0 14px 28px rgba(0, 0, 0, 0.4),
    0 0 30px rgba(195, 239, 131, 0.1),
    0 0 0 1px rgba(195, 239, 131, 0.15) inset;
}

/* QUIZ VISUAL */
.quiz-visual { position: absolute; top: 56px; right: 18px; left: 18px; }
.quiz-question b { display: block; margin-top: 4px; color: #d9d9d4; font-size: 10px; font-weight: 550; }
