  transform: translateX(2px);
}
.quiz-option.correct {
  border-color: rgba(195, 239, 131, 0.5);
  background: rgba(195, 239, 131, 0.09);
  color: #e5f5d3;
}
.quiz-option.correct > span { background: rgba(195, 239, 131, 0.25); color: var(--lime); }
.quiz-option > span {
  display: grid;
  width: 15px;
  height: 15px;
  place-items: center;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  color: #92968f;
  font-size: 8px;
  font-weight: bold;
}

/* AUDIO COVER & LIVE WAVEFORM */
.audio-visual {
  position: absolute;
  top: 62px;
  right: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 11px;
}
.audio-cover {
  position: relative;
