.profile-menu button:disabled {
  cursor: wait;
  opacity: 0.6;
}

/* Dashboard Content */
.dashboard-content {
  position: relative;
  width: min(1220px, 100%);
  margin: 0 auto;
  padding: 38px clamp(24px, 4vw, 56px) 60px;
}
.dashboard-welcome {
  position: relative;
  display: flex;
  min-height: 190px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  animation: smoothReveal 0.8s var(--ease-spring) both;
}
.welcome-copy {
  position: relative;
  z-index: 1;
  max-width: 510px;
  padding: 4px 0;
}
.dashboard-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #8c9194;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
}
.dashboard-eyebrow > span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--dash-lime);
  box-shadow: 0 0 10px rgba(195, 239, 131, 0.7);
  animation: softPulse 2s ease-in-out infinite;
}
.welcome-copy h1 {
  margin: 14px 0 10px;
  color: #f1f0ec;
  font-size: clamp(34px, 4vw, 48px);
  font-weight: 650;
  letter-spacing: -2px;
  line-height: 1.08;
}
.welcome-copy h1 > span {
  color: var(--dash-lime);
  animation: textGlow 3s ease-in-out infinite;
}
.welcome-copy p {
  max-width: 440px;
  margin: 0;
  color: #8c9194;
  font-size: 12px;
  line-height: 1.7;
}
.welcome-art-wrap {
  position: absolute;
  top: 0;
  right: 24%;
  width: 250px;
  height: 190px;
  animation: floatSmooth 6s ease-in-out infinite;
  pointer-events: none;
}
.study-illustration {
  position: absolute;
  z-index: 1;
  right: 8px;
  bottom: -6px;
  width: 210px;
  height: 166px;
  filter: drop-shadow(0 12px 25px rgba(0, 0, 0, 0.5));
}
/* ─── PROMINENT REVOLVING ORBITAL RINGS ─── */
.welcome-art-orbit {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

/* Orbit A: Electric Lime Orbit */
.welcome-art-orbit.orbit-a {
  top: 14px;
  left: 14px;
  width: 220px;
  height: 134px;
  border: 2px solid rgba(195, 239, 131, 0.65);
  box-shadow: 
    0 0 16px rgba(195, 239, 131, 0.35),
    inset 0 0 12px rgba(195, 239, 131, 0.15);
  transform-origin: 50% 50%;
  animation: orbitRevolveA 12s linear infinite;
}

/* Orbit B: Cyber Cyan Orbit */
.welcome-art-orbit.orbit-b {
  top: 32px;
  left: 30px;
  width: 194px;
  height: 106px;
  border: 2px solid rgba(134, 197, 237, 0.65);
  box-shadow: 
    0 0 16px rgba(134, 197, 237, 0.35),
    inset 0 0 12px rgba(134, 197, 237, 0.15);
  transform-origin: 50% 50%;
  animation: orbitRevolveB 16s linear infinite reverse;
}

/* Orbit C: Vibrant Golden-Orange Orbit */
.welcome-art-orbit.orbit-c {
  top: 24px;
  left: 40px;
  width: 176px;
  height: 120px;
  border: 1.8px dashed rgba(255, 122, 51, 0.7);
  box-shadow: 
    0 0 16px rgba(255, 107, 43, 0.35),
    inset 0 0 10px rgba(255, 107, 43, 0.15);
  transform-origin: 50% 50%;
  animation: orbitRevolveC 20s linear infinite;
}

/* Keyframes for smooth continuous 360-degree orbital revolutions */
@keyframes orbitRevolveA {
  from { transform: rotate(-18deg) rotate(0deg); }
  to { transform: rotate(-18deg) rotate(360deg); }
}

@keyframes orbitRevolveB {
  from { transform: rotate(34deg) rotate(0deg); }
  to { transform: rotate(34deg) rotate(360deg); }
}

@keyframes orbitRevolveC {
  from { transform: rotate(-52deg) rotate(0deg); }
  to { transform: rotate(-52deg) rotate(360deg); }
}

/* Revolving satellites / electron nodes */
.orbit-satellite {
  position: absolute;
  top: -5px;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 50%;
  animation: satPulse 1.8s ease-in-out infinite alternate;
}

.orbit-satellite.sat-lime {
  width: 10px;
  height: 10px;
  background: #c3ef83;
  box-shadow: 0 0 14px #c3ef83, 0 0 5px #ffffff;
}

.orbit-satellite.sat-cyan {
  width: 9px;
  height: 9px;
  background: #86c5ed;
  box-shadow: 0 0 14px #86c5ed, 0 0 5px #ffffff;
}

.orbit-satellite.sat-orange {
  width: 8px;
  height: 8px;
  background: #ff7a33;
  box-shadow: 0 0 14px #ff7a33, 0 0 5px #ffffff;
}

@keyframes satPulse {
  0% { transform: translateX(-50%) scale(0.85); opacity: 0.85; }
  100% { transform: translateX(-50%) scale(1.2); opacity: 1; }
}

html[data-theme="light"] .welcome-art-orbit.orbit-a {
  border-color: rgba(16, 149, 107, 0.7);
  box-shadow: 0 0 14px rgba(16, 149, 107, 0.3);
}
html[data-theme="light"] .welcome-art-orbit.orbit-b {
  border-color: rgba(2, 132, 199, 0.7);
  box-shadow: 0 0 14px rgba(2, 132, 199, 0.3);
}
html[data-theme="light"] .welcome-art-orbit.orbit-c {
  border-color: rgba(234, 88, 12, 0.7);
  box-shadow: 0 0 14px rgba(234, 88, 12, 0.3);
}
.welcome-speech {
  position: absolute;
  z-index: 10;
  top: -12px;
  right: 18px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border: 1.5px solid var(--lime);
  border-radius: 8px;
  background: rgba(17, 22, 29, 0.96);
  color: #f1f0ec;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  box-shadow: 
    0 8px 24px rgba(0, 0, 0, 0.55),
    0 0 16px rgba(195, 239, 131, 0.3);
  backdrop-filter: blur(12px);
  transform-origin: 50% 140%;
  pointer-events: none;
  transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1), transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.welcome-speech.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.welcome-speech.is-hidden {
  opacity: 0;
  transform: translateY(34px) scale(0.15);
}

html[data-theme="light"] .welcome-speech {
  background: #ffffff;
  color: #11140e;
  border-color: #1a7f5a;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15), 0 0 12px rgba(26, 127, 90, 0.25);
}

.welcome-speech .speech-text {
  color: var(--lime);
  text-shadow: 0 0 8px rgba(195, 239, 131, 0.4);
}
html[data-theme="light"] .welcome-speech .speech-text {
  color: #16704f;
  text-shadow: none;
}

.welcome-speech .speech-spark {
  font-size: 11px;
  animation: starTwinkle 1.4s ease-in-out infinite alternate;
}

.welcome-speech .speech-cursor {
  display: inline-block;
  width: 4px;
  height: 9px;
  background: var(--lime);
  margin-left: 2px;
  animation: cursorBlink 0.9s steps(2, start) infinite;
}
html[data-theme="light"] .welcome-speech .speech-cursor {
  background: #16704f;
}

/* Dialogue stem pointing straight into the computer monitor */
.welcome-speech .speech-tail {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
}
.welcome-speech .speech-tail span {
  display: block;
  background: var(--lime);
}
.welcome-speech .speech-tail .tail-1 { width: 8px; height: 3px; }
.welcome-speech .speech-tail .tail-2 { width: 5px; height: 3px; }
.welcome-speech .speech-tail .tail-3 { width: 2px; height: 3px; }

html[data-theme="light"] .welcome-speech .speech-tail span {
  background: #1a7f5a;
}
.encouragement-card {
  position: relative;
  z-index: 2;
  display: flex;
  min-width: 210px;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.9), rgba(16, 19, 23, 0.95));
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(14px);
  transition: all 0.25s var(--ease-spring);
}
.encouragement-card:hover {
  transform: translateY(-2px);
  border-color: rgba(195, 239, 131, 0.35);
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.5), 0 0 20px rgba(195, 239, 131, 0.08);
}
.encouragement-icon {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  place-items: center;
  border-radius: 9px;
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
}
.encouragement-card > span:nth-child(2) {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
}
.encouragement-card b {
  color: #f1f0ec;
  font-size: 10px;
}
.encouragement-card small {
  color: #8c9194;
  font-size: 8px;
}
.encouragement-bars {
  display: flex;
  height: 23px;
  align-items: flex-end;
  gap: 3px;
}
.encouragement-bars i {
  width: 4px;
  border-radius: 3px 3px 1px 1px;
  background: rgba(195, 239, 131, 0.35);
}
.encouragement-bars i:nth-child(1) { height: 9px; }
.encouragement-bars i:nth-child(2) { height: 15px; }
.encouragement-bars i:nth-child(3) { height: 21px; background: var(--dash-lime); box-shadow: 0 0 8px rgba(195, 239, 131, 0.6); }

/* Study Prompt Card */
.study-prompt-card {
  position: relative;
  z-index: 1;
  margin-bottom: 18px;
  padding: 20px 22px 18px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.94), rgba(16, 19, 23, 0.98));
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.45), 0 0 35px rgba(195, 239, 131, 0.05);
  backdrop-filter: blur(20px);
  transition: border-color 0.3s var(--ease-spring), box-shadow 0.3s;
}
.study-prompt-card:focus-within {
  border-color: rgba(195, 239, 131, 0.35);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.55), 0 0 45px rgba(195, 239, 131, 0.1);
}
.prompt-tip {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  color: #8c9194;
  font-size: 10px;
  font-weight: 500;
}
.prompt-tip svg {
  color: var(--dash-lime);
}
.prompt-form {
  display: flex;
