result.content:
/* BENTO GRID */
.bento-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 280px 286px;
  gap: 14px;
}
.feature-card {
  position: relative;
  overflow: hidden;
  padding: 18px 18px 15px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: linear-gradient(145deg, rgba(22, 26, 31, 0.94), rgba(16, 19, 23, 0.98));
  transition: all 0.3s var(--ease-spring);
  backdrop-filter: blur(20px);
}
.feature-card:hover {
  transform: translateY(-4px);
  border-color: rgba(195, 239, 131, 0.4);
  box-shadow: 
    0 16px 36px rgba(0, 0, 0, 0.4), 
    0 0 25px rgba(195, 239, 131, 0.08),
    0 0 0 1px rgba(195, 239, 131, 0.1) inset;
}
.feature-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(195, 239, 131, 0.03), transparent 60%);
  opacity: 0;
  transition: opacity 0.3s var(--ease-spring);
  pointer-events: none;
}
.feature-card:hover::before {
  opacity: 1;
}
.flash-card { grid-column: 1; grid-row: 1; }
.quiz-card { grid-column: 2; grid-row: 1; }
.audio-card { grid-column: 3; grid-row: 1; }
.mindmap-card { grid-column: 1 / 3; grid-row: 2; }
.planner-card { grid-column: 3; grid-row: 2; }

.card-topline {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.feature-icon {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  transition: transform 0.25s var(--ease-spring), box-shadow 0.25s var(--ease-spring);
}
.feature-card:hover .feature-icon {
  transform: scale(1.1);
  box-shadow: 0 0 20px rgba(195, 239, 131, 0.3);
}
.lime-icon { color: var(--lime); background: rgba(195, 239, 131, 0.1); }
.card-number { color: #71777b; font-size: 8px; letter-spacing: 1.2px; font-weight: 600; }

.feature-copy {
  position: absolute;
  z-index: 2;
  right: 18px;
  bottom: 16px;
  left: 18px;
}
.feature-copy h3 {
  margin: 0 0 5px;
  color: #e9eae5;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.2px;
}
.feature-copy p { margin: 0; color: #858b8e; font-size: 10px; line-height: 1.55; }

/* 3D REAL FLASHCARD FLIP MECHANICS */
.flash-visual {
  position: absolute;
  top: 53px;
  right: 18px;
  left: 18px;
  height: 140px;
  display: grid;
  place-items: center;
  perspective: 1000px;
}
.flashcard-3d-wrapper {
  width: 88%;
  height: 118px;
  cursor: pointer;
  position: relative;
}
.flashcard-3d-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: left;
  transition: transform 0.65s var(--ease-spring);
  transform-style: preserve-3d;
}
.flashcard-3d-inner.is-flipped {
  transform: rotateY(180deg);
}
.flashcard-face {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  border: 1px solid rgba(195, 239, 131, 0.28);
  border-radius: 10px;
  background: linear-gradient(135deg, #1c221b 0%, #121617 100%);
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-shadow: 
    0 14px 28px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(195, 239, 131, 0.05) inset;
}
.flashcard-face-back {
  transform: rotateY(180deg);
  background: linear-gradient(135deg, #182218 0%, #0e1411 100%);
  border-color: var(--lime);
  box-shadow: 
    0 14px 28px rgba(0, 0, 0, 0.4),
    0 0 30px rgba(195, 239, 131, 0.1),
    0 0 0 1px rgba(195, 239, 131, 0.15) inset;
}

/* QUIZ VISUAL */
.quiz-visual { position: absolute; top: 56px; right: 18px; left: 18px; }
.quiz-question b { display: block; margin-top: 4px; color: #d9d9d4; font-size: 10px; font-weight: 550; }
.quiz-option {
  display: flex;
  height: 27px;
  align-items: center;
  gap: 7px;
  margin-top: 5px;
  padding: 0 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 5px;
  color: #9b9e9b;
  font-size: 8px;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.quiz-option:hover {
  border-color: rgba(195, 239, 131, 0.3);
  color: #ffffff;
  transform: translateX(2px);
}
.quiz-option.correct {
  border-color: rgba(195, 239, 131, 0.5);
  background: rgba(195, 239, 131, 0.09);
  color: #e5f5d3;
}
.quiz-option.correct > span { background: rgba(195, 239, 131, 0.25); color: var(--lime); }
.quiz-option > span {
  display: grid;
  width: 15px;
  height: 15px;
  place-items: center;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  color: #92968f;
  font-size: 8px;
  font-weight: bold;
}

/* AUDIO COVER & LIVE WAVEFORM */
.audio-visual {
  position: absolute;
  top: 62px;
  right: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 11px;
}
.audio-cover {
  position: relative;
  display: flex;
  width: 88px;
  height: 102px;
  flex: 0 0 88px;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  padding: 10px;
  border: 1px solid rgba(195, 239, 131, 0.22);
  border-radius: 8px;
  background: linear-gradient(150deg, #182216 0%, #11151a 100%);
  color: var(--lime);
  transition: all 0.3s var(--ease-spring);
}
.audio-cover::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(195, 239, 131, 0.15), transparent 70%);
  opacity: 0;
  transition: opacity 0.3s;
}
.audio-card:hover .audio-cover::before { opacity: 1; }
.waveform { display: flex; height: 26px; align-items: center; gap: 2px; }
.waveform i {
  width: 2px;
  border-radius: 2px;
  background: var(--lime);
  opacity: 0.8;
  transform-origin: bottom;
  transition: transform 0.2s;
}
/* When audio is active, waveform dances with staggered delays */
.waveform.is-active i {
  animation: waveDance 1.2s ease-in-out infinite alternate;
}
.waveform.is-active i:nth-child(2n) { animation-delay: 0.15s; }
.waveform.is-active i:nth-child(3n) { animation-delay: 0.3s; }
.waveform.is-active i:nth-child(4n) { animation-delay: 0.45s; }
.waveform.is-active i:nth-child(5n) { animation-delay: 0.6s; }

.audio-play {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 50%;
  background: var(--lime);
  color: #11140e;
  cursor: pointer;

