/* AUDIO COVER & LIVE WAVEFORM */
.audio-visual {
  position: absolute;
  top: 62px;
  right: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 11px;
}
.audio-cover {
  position: relative;
  display: flex;
  width: 88px;
  height: 102px;
  flex: 0 0 88px;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  padding: 10px;
  border: 1px solid rgba(195, 239, 131, 0.22);
  border-radius: 8px;
  background: linear-gradient(150deg, #182216 0%, #11151a 100%);
  color: var(--lime);
  transition: all 0.3s var(--ease-spring);
}
.audio-cover::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(195, 239, 131, 0.15), transparent 70%);
  opacity: 0;
  transition: opacity 0.3s;
}
.audio-card:hover .audio-cover::before { opacity: 1; }
.waveform { display: flex; height: 26px; align-items: center; gap: 2px; }
.waveform i {
  width: 2px;
  border-radius: 2px;
  background: var(--lime);
  opacity: 0.8;
  transform-origin: bottom;
  transition: transform 0.2s;
}
/* When audio is active, waveform dances with staggered delays */
.waveform.is-active i {
  animation: waveDance 1.2s ease-in-out infinite alternate;
}
.waveform.is-active i:nth-child(2n) { animation-delay: 0.15s; }
.waveform.is-active i:nth-child(3n) { animation-delay: 0.3s; }
.waveform.is-active i:nth-child(4n) { animation-delay: 0.45s; }
.waveform.is-active i:nth-child(5n) { animation-delay: 0.6s; }

.audio-play {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 50%;
  background: var(--lime);
  color: #11140e;
  cursor: pointer;
  transition: transform 0.25s var(--ease-spring), box-shadow 0.25s;
}
.audio-play:hover {
  transform: scale(1.15);
  box-shadow: 0 0 14px rgba(195, 239, 131, 0.5);
}

/* MINDMAP */
.mindmap-visual { position: absolute; inset: 47px 0 46px; }
.map-lines i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 110px;
  height: 1px;
  background: linear-gradient(90deg, rgba(195, 239, 131, 0.4), rgba(255, 255, 255, 0.05));
  transform-origin: 0 50%;
}
.map-lines i:nth-child(1) { transform: rotate(180deg); }
.map-lines i:nth-child(2) { transform: rotate(218deg); }
.map-lines i:nth-child(3) { transform: rotate(142deg); }
.map-lines i:nth-child(4) { transform: rotate(35deg); }
.map-lines i:nth-child(5) { transform: rotate(-35deg); }
.map-lines i:nth-child(6) { transform: rotate(0); }
