  background: transparent;
  color: #fff;
  transition: background 180ms ease, border-color 180ms ease, transform 180ms ease;
}
.task-checkbox[aria-pressed="true"] { border-color: #16877e; background: #16877e; }
.task-checkbox:hover { transform: scale(1.08); }
.task-priority-tag {
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 700;
}
.task-priority-tag.high { background: rgba(239, 68, 68, .12); color: #ef4444; }
.task-priority-tag.medium { background: rgba(245, 158, 11, .14); color: #d97706; }
.task-priority-tag.low { background: rgba(59, 130, 246, .12); color: #3b82f6; }
.agenda-deadline {
  min-width: 52px;
  color: var(--dash-muted);
  font-size: 10px;
  text-align: right;
}
.agenda-deadline.overdue { color: #ef4444; }
.agenda-task.completed .agenda-task-title::after,
.task-list-item.completed .task-list-title::after {
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  height: 1px;
  background: currentColor;
  content: "";
  transform: scaleX(1);
  transform-origin: left;
  transition: transform 260ms ease;
}
.notebooks-heading { align-items: center; }
.notebooks-title h2 { font-size: 23px; }
.notebook-tools { flex-wrap: wrap; }
.new-notebook-button.secondary {
  border-color: var(--dash-border);
  background: transparent;
  color: var(--dash-text);
  box-shadow: none;
}
.new-notebook-button.secondary:hover { background: var(--dash-card); }
.notebook-card-entry { min-width: 0; display: grid; gap: 7px; }
.notebook-card-entry > select {
  width: 100%;
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--dash-border);
  border-radius: 9999px;
  background: var(--dash-panel);
  color: var(--dash-muted);
  font-size: 11px;
}
.notebook-workspace-tabs {
  display: flex;
  width: fit-content;
  gap: 5px;
  margin: 0 0 18px;
  padding: 5px;
  border: 1px solid var(--dash-border);
  border-radius: 9999px;
  background: var(--dash-panel);
}
.notebook-workspace-tabs button {
  padding: 8px 15px;
  border: 0;
  background: transparent;
  color: var(--dash-muted);
  font-size: 11px;
  font-weight: 600;
}
.notebook-workspace-tabs button.active {
  background: rgba(22, 135, 126, 0.14);
  color: var(--dash-lime);
}
.citation-chip {
  display: inline-flex;
  margin: 0 2px;
  padding: 1px 7px;
  border: 1px solid rgba(139, 92, 246, 0.3);
  background: rgba(139, 92, 246, 0.11);
  color: #a78bfa;
  font-size: 10px;
  font-weight: 700;
  vertical-align: baseline;
  transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}
.citation-chip:hover {
  transform: translateY(-1px);
  background: rgba(139, 92, 246, 0.2);
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.08);
}
.assistant-message-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}
.assistant-message-actions button,
.citation-preview button {
  padding: 6px 11px;
  border: 1px solid var(--dash-border);
  background: transparent;
  color: var(--dash-muted);
  font-size: 10px;
  font-weight: 600;
}
.assistant-message-actions button:hover,
.citation-preview button:hover { border-color: var(--dash-border-hover); color: var(--dash-lime); }
.citation-preview {
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(139, 92, 246, 0.25);
  border-radius: 14px;
  background: rgba(139, 92, 246, 0.06);
}
.citation-preview b { color: #a78bfa; font-size: 10px; }
.citation-preview p { margin: 6px 0 10px; color: var(--dash-text); font-size: 11px; line-height: 1.65; }
.task-create-form {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) 140px 130px 150px auto;
  gap: 9px;
  margin: 20px 0;
}
.task-create-form input,
.task-create-form select,
.task-list-item select {
  min-width: 0;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--dash-border);
  border-radius: 9999px;
  background: var(--dash-panel);
  color: var(--dash-text);
  font-size: 11px;
}
.task-filter-tabs { display: flex; flex-wrap: wrap; gap: 7px; margin: 18px 0 12px; }
.task-filter-tabs button,
.folder-filter-pill {
  padding: 8px 14px;
  border: 1px solid var(--dash-border);
  background: transparent;
  color: var(--dash-muted);
  font-size: 11px;
  font-weight: 600;
}
.task-filter-tabs button.active,
.folder-filter-pill.active {
  border-color: rgba(22, 135, 126, 0.35);
  background: rgba(22, 135, 126, 0.12);
  color: var(--dash-lime);
}
.task-list { display: grid; gap: 8px; }
.task-list-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--dash-border);
  border-radius: 16px;
  background: var(--dash-card);
  transition: opacity 220ms ease, border-color 220ms ease, transform 220ms ease;
}
.task-list-item.completed { opacity: .7; }
.task-list-item select { min-height: 32px; width: 130px; }
.task-due-date { min-width: 78px; color: var(--dash-muted); font-size: 10px; text-align: right; }
.task-due-date.overdue { color: #ef4444; }
.task-delete-button { padding: 7px; border: 0; background: transparent; color: var(--dash-muted); }
.task-delete-button:hover { background: rgba(239, 68, 68, .1); color: #ef4444; }
.topbar-pill-button {
  min-height: 34px;
  padding: 0 14px;
  border: 1px solid var(--dash-border);
  background: var(--dash-panel);
  color: var(--dash-text);
  font-size: 11px;
  font-weight: 650;
}
.topbar-pill-button:hover { transform: translateY(-1px); border-color: var(--dash-border-hover); }
.upgrade-pill { border-color: rgba(139, 92, 246, .3); background: rgba(139, 92, 246, .12); color: #a78bfa; }
.feedback-overlay {
  position: fixed;
  z-index: 120;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 9, 12, .62);
  backdrop-filter: blur(7px);
}
.feedback-dialog {
  width: min(440px, 100%);
  padding: 24px;
  border: 1px solid var(--dash-border);
  border-radius: 22px;
  background: var(--dash-panel);
  box-shadow: 0 24px 80px rgba(0, 0, 0, .25);
}
.feedback-dialog h2 { margin: 0 0 6px; color: var(--dash-text); font-size: 20px; }
.feedback-dialog p { margin: 0 0 16px; color: var(--dash-muted); font-size: 12px; }
.feedback-dialog textarea {
  width: 100%;
  min-height: 130px;
  resize: vertical;
  padding: 12px;
  border: 1px solid var(--dash-border);
  border-radius: 14px;
  outline: none;
  background: var(--dash-card);
  color: var(--dash-text);
  font: inherit;
}
.feedback-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 14px; }
.feedback-dialog-actions button { padding: 9px 14px; border: 1px solid var(--dash-border); background: transparent; color: var(--dash-text); font-size: 11px; }
.feedback-dialog-actions button[type="submit"] { border-color: transparent; background: #16877e; color: white; }

html[data-theme="light"] .study-prompt-card,
html[data-theme="light"] .agenda-widget,
html[data-theme="light"] .task-list-item,
html[data-theme="light"] .feedback-dialog { background: #fff; border-color: rgba(32, 67, 62, .13); }
html[data-theme="light"] .agenda-task-title,
html[data-theme="light"] .task-list-title,
html[data-theme="light"] .agenda-heading h2 { color: #1b2928; }
html[data-theme="light"] .agenda-heading > button,
html[data-theme="light"] .assistant-message-actions button,
html[data-theme="light"] .citation-preview button,
html[data-theme="light"] .notebook-workspace-tabs,
html[data-theme="light"] .task-create-form input,
html[data-theme="light"] .task-create-form select,
html[data-theme="light"] .task-list-item select,
html[data-theme="light"] .notebook-card-entry > select { background: #fff; border-color: rgba(32, 67, 62, .14); color: #52635f; }
html[data-theme="light"] .citation-preview { background: rgba(139, 92, 246, .06); }
html[data-theme="light"] .citation-preview p { color: #344946; }
html[data-theme="light"] .prompt-form input { color: #1b2928; }
html[data-theme="light"] .source-action { border-color: rgba(32, 67, 62, .14); background: #f7faf9; color: #374745; }
html[data-theme="light"] .new-notebook-button.secondary { color: #1b2928; }
@media (max-width: 900px) {
  .task-create-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .task-create-form input:first-child { grid-column: 1 / -1; }
  .bento-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: auto; }
  .flash-card, .quiz-card, .mindmap-card, .planner-card { grid-column: auto; grid-row: auto; min-height: 280px; }
  .mindmap-card { grid-column: 1 / -1; }
}
@media (max-width: 560px) {
  .topbar-actions { gap: 5px; }
  .topbar-pill-button { min-height: 30px; padding-inline: 9px; font-size: 9px; }
  .welcome-art-wrap { display: block; transform: scale(.82); transform-origin: center; margin-block: -18px -12px; }
  .welcome-copy h1 { font-size: 34px; line-height: 1.1; }
  .dashboard-eyebrow { justify-content: center; }
  .agenda-widget { padding: 16px; }
  .agenda-heading { align-items: flex-start; }
  .agenda-heading h2 { font-size: 16px; }
  .agenda-heading > button { white-space: nowrap; font-size: 9px; }
  .agenda-task { gap: 7px; }
  .agenda-task-title { font-size: 10px; }
  .task-priority-tag { padding: 3px 6px; font-size: 8px; }
  .agenda-deadline { min-width: 40px; font-size: 9px; }
  .notebooks-heading { align-items: flex-start; }
  .notebook-tools { justify-content: flex-start; }
  .task-create-form { grid-template-columns: 1fr; }
  .task-create-form input:first-child { grid-column: auto; }
  .task-list-item { flex-wrap: wrap; gap: 8px; }
  .task-list-title { flex: 1 1 calc(100% - 35px); }
  .task-list-item select { width: auto; flex: 1; }
  .task-due-date { min-width: auto; }
  .notebook-workspace-tabs { max-width: 100%; overflow-x: auto; }
  .notebook-workspace-tabs button { white-space: nowrap; padding-inline: 12px; }
}

