 }
 .assistant-message-actions {
   display: flex;
   gap: 8px;
   margin-top: 12px;
 }
 .assistant-message-actions button,
 .citation-preview button {
   padding: 6px 11px;
   border: 1px solid var(--dash-border);
   background: transparent;
   color: var(--dash-muted);
   font-size: 10px;
   font-weight: 600;
 }
 .assistant-message-actions button:hover,
 .citation-preview button:hover { border-color: var(--dash-border-hover); color: var(--dash-lime); }
 .citation-preview {
