  background: transparent;
  color: var(--dash-muted);
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.dashboard-sidebar .sidebar-collapse-btn:hover {
  background: rgba(195, 239, 131, 0.1);
  border-color: rgba(195, 239, 131, 0.2);
  color: var(--dash-lime);
}

/* Collapsed sidebar state */
.dashboard-shell[data-sidebar-collapsed="true"] .dashboard-sidebar {
  width: 72px;
  flex: 0 0 72px;
}
.dashboard-shell[data-sidebar-collapsed="true"] .brand-text {
  opacity: 0;
  width: 0;
}
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-label,
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-note,
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-footer,
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-spacer {
  display: none;
}
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-link {
  justify-content: center;
  padding: 0;
}
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-link span {
  display: none;
}
.dashboard-shell[data-sidebar-collapsed="true"] .nav-new {
  display: none;
}
.dashboard-shell[data-sidebar-collapsed="true"] .sidebar-collapse-btn {
  transform: rotate(180deg);
}
.dashboard-shell[data-sidebar-collapsed="true"] .dashboard-main {
  margin-left: 72px;
}
.dashboard-shell[data-sidebar-collapsed="true"] .mobile-sidebar-toggle {
  left: 88px;
}

/* Main content margin for normal sidebar */
.dashboard-main {
  margin-left: 240px;
  transition: margin-left 0.3s var(--ease-spring);
  min-height: 100vh;
}

/* Encouragement banner at top */
.encouragement-banner {
  margin: 16px 24px 8px;
  padding: 12px 16px;
  border: 1px solid var(--dash-border);
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(195, 239, 131, 0.06), rgba(22, 135, 126, 0.04));
  animation: slideUpFade 0.6s var(--ease-spring) both;
}
.encouragement-content {
  display: flex;
  align-items: center;
  gap: 12px;
}
.encouragement-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 8px;
  background: rgba(195, 239, 131, 0.12);
  color: var(--dash-lime);
  flex-shrink: 0;
}
.encouragement-content > span:first-of-type {
  flex: 1;
  min-width: 0;
}
.encouragement-content b {
  color: var(--dash-text);
  font-size: 13px;
  font-weight: 600;
}
.encouragement-content small {
  display: block;
  margin-top: 2px;
  color: var(--dash-muted);
  font-size: 11px;
}
.encouragement-bars {
  display: flex;
  align-items: end;
  gap: 3px;
  height: 28px;
  flex-shrink: 0;
}
.encouragement-bars i {
  width: 5px;
  border-radius: 3px 3px 0 0;
  background: linear-gradient(180deg, var(--dash-lime), var(--dash-cyan));
  animation: barGrow 1.2s ease-out infinite;
}
.encouragement-bars i:nth-child(1) { height: 40%; animation-delay: 0s; }
.encouragement-bars i:nth-child(2) { height: 65%; animation-delay: 0.15s; }
.encouragement-bars i:nth-child(3) { height: 85%; animation-delay: 0.3s; }

@keyframes barGrow {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(0.6); }
}

/* Profile avatar */
.profile-avatar-img,
.profile-avatar-fallback {
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--dash-border);
  background: var(--dash-card);
  color: var(--dash-lime);
  font-weight: 700;
}

/* Profile button */
.profile-button {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px 6px 6px;
  border: 1px solid var(--dash-border);
  border-radius: 999px;
  background: var(--dash-panel);
  color: var(--dash-text);
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.profile-button:hover {
  border-color: var(--dash-border-hover);
  background: var(--dash-card);
  box-shadow: 0 0 15px rgba(195, 239, 131, 0.08);
}
.profile-name {
  font-size: 12px;
  font-weight: 550;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Profile menu */
.profile-wrap {
  position: relative;
}
.profile-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  min-width: 260px;
  padding: 10px;
  border: 1px solid var(--dash-border);
  border-radius: 12px;
  background: var(--dash-panel);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25), 0 0 0 1px rgba(195, 239, 131, 0.05) inset;
  backdrop-filter: blur(20px);
  z-index: 100;
  animation: slideUpFade 0.25s var(--ease-spring);
}
.profile-menu-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 4px 12px;
  border-bottom: 1px solid var(--dash-border);
}
.profile-menu-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.profile-menu-info b {
  color: var(--dash-text);
  font-size: 14px;
  font-weight: 600;
}
.profile-menu-info span {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--dash-muted);
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.profile-provider {
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime) !important;
  font-weight: 550;
  font-size: 10px !important;
}
.profile-menu-divider {
  height: 1px;
  margin: 4px 0;
  background: var(--dash-border);
}
.profile-menu button {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--dash-text);
  font-size: 12px;
  font-weight: 550;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.profile-menu button:hover {
  background: rgba(195, 239, 131, 0.08);
  border-color: rgba(195, 239, 131, 0.2);
  color: var(--dash-lime);
}
.profile-menu button:disabled {
  opacity: 0.6;
  cursor: wait;
}

/* Empty state enhancements */
.notebooks-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 48px 24px;
  text-align: center;
  color: var(--dash-muted);
}
.empty-mascot-icon {
  display: grid;
  width: 64px;
  height: 64px;
  place-items: center;
  border-radius: 16px;
  background: rgba(195, 239, 131, 0.08);
  color: var(--dash-lime);
}
.notebooks-empty b {
  color: var(--dash-text);
  font-size: 16px;
  font-weight: 600;
}
.notebooks-empty span {
  max-width: 360px;
  color: var(--dash-muted);
  font-size: 13px;
  line-height: 1.6;
}
.empty-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 8px;
  justify-content: center;
}
.empty-source-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border: 1px solid var(--dash-border);
  border-radius: 8px;
  background: var(--dash-panel);
  color: var(--dash-text);
  font-size: 12px;
  font-weight: 550;
  cursor: pointer;
  transition: all 0.2s var(--ease-spring);
}
.empty-source-button:hover {
  border-color: var(--dash-border-hover);
  background: var(--dash-card);
  color: var(--dash-lime);
}
.empty-source-button-alt {
  border-color: rgba(195, 239, 131, 0.3);
  background: rgba(195, 239, 131, 0.06);
  color: var(--dash-lime);
}
.empty-source-button-alt:hover {
  background: rgba(195, 239, 131, 0.12);
}

/* Notebook card tweaks */
.notebook-card {
  transition: transform 0.25s var(--ease-spring), box-shadow 0.25s var(--ease-spring), border-color 0.2s var(--ease-spring);
}
.notebook-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.15);
}

/* Search input */
.notebook-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid var(--dash-border);
  border-radius: 8px;
  background: var(--dash-panel);
  color: var(--dash-text);
}
.notebook-search input {
  width: 100%;
  height: 36px;
  border: none;
  background: transparent;
  color: var(--dash-text);
  font-size: 13px;
  outline: none;
}
.notebook-search input::placeholder {
  color: var(--dash-subtle);
}
.notebook-search button {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: none;
  background: transparent;
  color: var(--dash-muted);
  cursor: pointer;
  border-radius: 6px;
  transition: all 0.2s;
}
.notebook-search button:hover {
  background: rgba(195, 239, 131, 0.1);
  color: var(--dash-lime);
}

/* Responsive */
@media (max-width: 700px) {
  .topbar .topbar-actions { gap: 7px; }
  .theme-toggle { min-height: 34px; gap: 6px; padding: 0 8px; }
}

/* Smooth, transform-only motion avoids the blur/layout work behind the janky effects. */
:root {
  --mascot-teal: #167f77;
  --mascot-screen: #0a1310;
  --mascot-screen-bezel: #141b24;
  --mascot-ink: #16302e;
  --mascot-pixel: #f5f4ed;
  --mascot-coral: #fb7185;
  --mascot-chassis: #1e2633;
  --mascot-chassis-light: #2e3a4d;
  --mascot-chassis-dark: #10151f;
  --mascot-eye: #c3ef83;
  --mascot-eye-cyan: #86c5ed;
  --mascot-spark: #c3ef83;
  --mascot-desk: #18202a;
  --mascot-desk-wood: #1e2836;
  --mascot-shadow: rgba(0, 0, 0, 0.45);
}
html[data-theme="light"] {
  --mascot-teal: #16877e;
  --mascot-screen: #0d1714;
  --mascot-screen-bezel: #1e2632;
  --mascot-ink: #24413d;
  --mascot-pixel: #f5f4ed;
  --mascot-coral: #f43f5e;
  --mascot-chassis: #253040;
  --mascot-chassis-light: #37465b;
  --mascot-chassis-dark: #151c27;
  --mascot-eye: #a3e635;
  --mascot-eye-cyan: #38bdf8;
  --mascot-spark: #a3e635;
  --mascot-desk: #e2e8f0;
  --mascot-desk-wood: #cbd5e1;
  --mascot-shadow: rgba(25, 62, 57, 0.2);
}

.reveal-on-scroll {
  opacity: 1;
  transform: none;
  filter: none;
  transition: opacity 700ms cubic-bezier(0.22, 1, 0.36, 1), transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.landing.reveal-enabled .reveal-on-scroll:not(.is-visible) {
  opacity: 0;
  transform: translate3d(0, 32px, 0);
  pointer-events: none;
  filter: none;
}
.reveal-on-scroll.is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  pointer-events: auto;
  filter: none;
}
.reveal-on-scroll.delay-1 { transition-delay: 0.09s; }
.reveal-on-scroll.delay-2 { transition-delay: 0.18s; }
.reveal-on-scroll.delay-3 { transition-delay: 0.27s; }
.reveal-on-scroll.delay-4 { transition-delay: 0.36s; }
.reveal-on-scroll.delay-5 { transition-delay: 0.45s; }

.feature-card {
  transition: transform 320ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 320ms cubic-bezier(0.22, 1, 0.36, 1), border-color 280ms ease !important;
}
.feature-card.is-revealed { animation-duration: 700ms; }
.section-heading { transition: opacity 700ms cubic-bezier(0.22, 1, 0.36, 1), transform 700ms cubic-bezier(0.22, 1, 0.36, 1); }
.feature-section::before, .learn-mode-section::before, .comparison-section::before {
  transform: translateX(-50%);
  animation: sectionDividerGlow 3s ease-in-out infinite;
}
@keyframes sectionDividerGlow {
  0%, 100% { transform: translateX(-50%) scaleX(0.55); opacity: 0.3; }
  50% { transform: translateX(-50%) scaleX(1); opacity: 0.65; }
}
.preview-window { animation: none; }
.float-chip { animation: none; transition: transform 260ms cubic-bezier(0.22, 1, 0.36, 1), border-color 240ms ease, box-shadow 240ms ease; }
.button-primary::after { animation: none; opacity: 0; transition: opacity 220ms ease; }
.button-primary:hover::after { opacity: 1; }
.topbar { animation-duration: 550ms; }
@keyframes smoothReveal {
  from { opacity: 0; transform: translate3d(0, 14px, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}
@keyframes authPanelEnter {
  from { opacity: 0; transform: translate3d(14px, 0, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}
@keyframes authAsideEnter {
  from { opacity: 0; transform: translate3d(-14px, 0, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}
@keyframes heroCopyEnter {
  from { opacity: 0; transform: translate3d(-18px, 10px, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}
@keyframes heroArtEnter {
  from { opacity: 0; transform: translate3d(18px, 10px, 0) scale(0.98); }
  to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}
@keyframes cardReveal {
  from { opacity: 0; transform: translate3d(0, 18px, 0) scale(0.99); }
  to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}

.dashboard-shell.reveal-enabled .dashboard-reveal:not(.is-revealed) {
  opacity: 0;
  transform: translate3d(0, 20px, 0);
}
.dashboard-reveal {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition: opacity 620ms cubic-bezier(0.22, 1, 0.36, 1), transform 620ms cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.pixel-mascot {
  image-rendering: pixelated;
  filter: drop-shadow(0 10px 18px rgba(20, 55, 50, 0.16));
  animation: mascotBob 3.6s ease-in-out infinite;
}
@keyframes mascotBob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}
@keyframes mascotBlink {
  0%, 90%, 100% { transform: scaleY(1); }
  94% { transform: scaleY(0.12); }
}
.pixel-mascot-eyes {
  transform-origin: 80px 54px;
  animation: mascotBlink 4.5s infinite ease-in-out;
}
.mascot-key {
  transform-box: fill-box;
  transform-origin: center top;
  animation: mascotKeyTap 1.8s steps(2, end) infinite;
}
.mascot-key.key-1 { animation-delay: 0.15s; }
.mascot-key.key-2 { animation-delay: 0.5s; }
.mascot-key.key-3 { animation-delay: 0.8s; }
.mascot-key.key-4 { animation-delay: 1.1s; }
.mascot-key.key-5 { animation-delay: 0.35s; }
.mascot-key.key-6 { animation-delay: 1.35s; }
@keyframes mascotKeyTap {
  0%, 13%, 100% { transform: translateY(0); }
  6% { transform: translateY(2px); }
}
.pixel-mascot-smile {
  transform-box: fill-box;
  transform-origin: center;
  animation: mascotSmile 3.4s ease-in-out infinite;
}
.pixel-mascot-open-smile {
  opacity: 0;
  animation: mascotOpenSmile 3.4s steps(1, end) infinite;
}
@keyframes mascotSmile {
  0%, 73%, 100% { transform: scaleY(1); }
  78%, 87% { transform: scaleY(0.35); }
  92% { transform: scaleY(1.2); }
}
@keyframes mascotOpenSmile {
  0%, 73%, 100% { opacity: 0; }
  78%, 87% { opacity: 1; }
}
@keyframes sparkTwinkle {
  0%, 100% { opacity: 0.9; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.18); }
}
.pixel-mascot-spark {
  transform-origin: 80px 9px;
  animation: sparkTwinkle 2.2s infinite ease-in-out;
}

