result.content:
  margin-bottom: 16px;
}
.task-summary-grid article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 68px;
  padding: 15px 18px;
  border: 1px solid var(--dash-border);
  border-radius: 16px;
  background: var(--dash-card);
}
.task-summary-grid article span { color: var(--dash-muted); font-size: 11px; font-weight: 550; }
.task-summary-grid article b { color: var(--dash-text); font-size: 22px; font-weight: 650; letter-spacing: -.6px; }
.task-create-form {
  display: grid;
  gap: 18px;
  margin: 0 0 24px;
  padding: 20px;
  border: 1px solid var(--dash-border);
  border-radius: 20px;
  background: var(--dash-card);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .08);
}
.task-title-field,
.task-create-details > label {
  display: grid;
  min-width: 0;
  gap: 7px;
}
.task-title-field > span,
.task-create-details > label > span {
  color: var(--dash-muted);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.task-title-field input,
.task-create-details input,
.task-create-details select {
  width: 100%;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid var(--dash-border);
  border-radius: 12px;
  outline: none;
  background: rgba(255, 255, 255, .035);
  color: var(--dash-text);
  font-size: 12px;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}
.task-title-field input:focus,
.task-create-details input:focus,
.task-create-details select:focus {
  border-color: var(--dash-border-hover);
  background: var(--dash-panel);
  box-shadow: 0 0 0 3px var(--dash-lime-glow);
}
.task-create-details {
  display: grid;
  grid-template-columns: 1.1fr .8fr 1fr auto;
  align-items: end;
  gap: 10px;
}
.task-create-details .module-primary-button {
  min-height: 42px;
  justify-content: center;
  padding-inline: 18px;
  white-space: nowrap;
}
.task-filter-tabs {
  width: fit-content;
  max-width: 100%;
  gap: 5px;
  margin: 0 0 12px;
  padding: 4px;
  border: 1px solid var(--dash-border);
  border-radius: 999px;
  background: var(--dash-panel);
}
.task-filter-tabs button {
  padding: 8px 13px;
  border-color: transparent;
}
.task-filter-tabs button.active {
  background: var(--dash-lime);
  color: #10201e;
}
.task-list { gap: 7px; }
.task-list-item {
  display: grid;
  grid-template-columns: 22px minmax(120px, 1fr) auto minmax(96px, auto) minmax(90px, auto) 32px;
  gap: 12px;
  min-height: 62px;
  padding: 11px 14px;
  border-radius: 14px;
  box-shadow: none;
}
.task-list-item:hover { border-color: var(--dash-border-hover); }
.task-list-title { font-size: 12px; font-weight: 550; }
.task-list-item select.task-status-select {
  width: auto;
  min-width: 105px;
  min-height: 30px;
  padding: 0 28px 0 11px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 600;
}
.task-status-select.to-do { color: #60a5fa; }
.task-status-select.in-progress { color: #f59e0b; }
.task-status-select.completed { color: #34d399; }
.task-due-date { font-size: 10px; }
html[data-theme="light"] .task-summary-grid article,
html[data-theme="light"] .task-create-form { border-color: rgba(32, 67, 62, .13); background: #fff; }
html[data-theme="light"] .task-title-field input,
html[data-theme="light"] .task-create-details input,
html[data-theme="light"] .task-create-details select {
  border-color: rgba(32, 67, 62, .14);
  background: #f7faf9;
  color: #1b2928;
}
html[data-theme="light"] .task-filter-tabs { background: #f7faf9; }
html[data-theme="light"] .task-filter-tabs button.active { color: #fff; }
html[data-theme="light"] .task-list-item select.task-status-select { background: #fff; }
@media (max-width: 760px) {
  .tasks-page-heading { align-items: flex-start; flex-direction: column; }
  .tasks-date-pill { align-self: flex-start; }
  .task-create-details { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .task-create-details .module-primary-button { grid-column: 1 / -1; }
  .task-list-item { grid-template-columns: 22px minmax(0, 1fr) auto 32px; }
  .task-list-item .task-priority-tag { grid-column: 2; justify-self: start; }
  .task-list-item .task-due-date { grid-column: 3; grid-row: 2; }
  .task-list-item .task-status-select { grid-column: 2 / 4; grid-row: 3; justify-self: start; }
  .task-list-item .task-delete-button { grid-column: 4; grid-row: 1; }
}
@media (max-width: 560px) {
  .task-summary-grid { gap: 7px; }
  .task-summary-grid article { min-height: 58px; align-items: flex-start; flex-direction: column; padding: 10px; }
  .task-summary-grid article span { font-size: 9px; }
  .task-summary-grid article b { font-size: 18px; }
  .task-create-form { padding: 14px; }
  .task-create-details { grid-template-columns: 1fr 1fr; }
  .task-create-details > label:first-child { grid-column: 1 / -1; }
  .task-filter-tabs { width: 100%; justify-content: space-between; }
  .task-filter-tabs button { padding-inline: 9px; font-size: 10px; }
}
@media (max-width: 900px) {
  .task-create-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .task-create-form input:first-child { grid-column: 1 / -1; }
  .bento-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: auto; }
  .flash-card, .quiz-card, .mindmap-card, .planner-card { grid-column: auto; grid-row: auto; min-height: 280px; }
  .mindmap-card { grid-column: 1 / -1; }
}
@media (max-width: 560px) {
  .welcome-art-wrap { display: block; transform: scale(.82); transform-origin: center; margin-block: -18px -12px; }
  .welcome-copy h1 { font-size: 34px; line-height: 1.1; }
  .dashboard-eyebrow { justify-content: center; }
  .agenda-widget { padding: 16px; }
  .agenda-heading { align-items: flex-start; }
  .agenda-heading h2 { font-size: 16px; }
  .agenda-heading > button { white-space: nowrap; font-size: 9px; }
  .agenda-task { gap: 7px; }
  .agenda-task-title { font-size: 10px; }
  .task-priority-tag { padding: 3px 6px; font-size: 8px; }
  .agenda-deadline { min-width: 40px; font-size: 9px; }
  .notebooks-heading { align-items: flex-start; }
  .notebook-tools { justify-content: flex-start; }
  .task-create-form { grid-template-columns: 1fr; }
  .task-create-form input:first-child { grid-column: auto; }
  .task-list-item { flex-wrap: wrap; gap: 8px; }
  .task-list-title { flex: 1 1 calc(100% - 35px); }
  .task-list-item select { width: auto; flex: 1; }
  .task-due-date { min-width: auto; }
  .notebook-workspace-tabs { max-width: 100%; overflow-x: auto; }
  .notebook-workspace-tabs button { white-space: nowrap; padding-inline: 12px; }
}

