.task-summary-grid article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 68px;
  padding: 15px 18px;
  border: 1px solid var(--dash-border);
  border-radius: 16px;
  background: var(--dash-card);
}
.task-summary-grid article span { color: var(--dash-muted); font-size: 11px; font-weight: 550; }
.task-summary-grid article b { color: var(--dash-text); font-size: 22px; font-weight: 650; letter-spacing: -.6px; }
.task-create-form {
  display: grid;
  gap: 18px;
  margin: 0 0 24px;
  padding: 20px;
  border: 1px solid var(--dash-border);
  border-radius: 20px;
  background: var(--dash-card);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .08);
}
.task-title-field,
.task-create-details > label {
  display: grid;
  min-width: 0;
  gap: 7px;
}
.task-title-field > span,
.task-create-details > label > span {
  color: var(--dash-muted);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.task-title-field input,
.task-create-details input,
.task-create-details select {
  width: 100%;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid var(--dash-border);
  border-radius: 12px;
  outline: none;
  background: rgba(255, 255, 255, .035);
  color: var(--dash-text);
  font-size: 12px;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}
.task-title-field input:focus,
.task-create-details input:focus,
.task-create-details select:focus {
  border-color: var(--dash-border-hover);
  background: var(--dash-panel);
  box-shadow: 0 0 0 3px var(--dash-lime-glow);
}
.task-create-details {
  display: grid;
  grid-template-columns: 1.1fr .8fr 1fr auto;
  align-items: end;
  gap: 10px;
}
.task-create-details .module-primary-button {
  min-height: 42px;
  justify-content: center;
  padding-inline: 18px;
  white-space: nowrap;
}
.task-filter-tabs {
  width: fit-content;
  max-width: 100%;
  gap: 5px;
  margin: 0 0 12px;
  padding: 4px;
  border: 1px solid var(--dash-border);
  border-radius: 999px;
  background: var(--dash-panel);
}
.task-filter-tabs button {
  padding: 8px 13px;
  border-color: transparent;
}
.task-filter-tabs button.active {
  background: var(--dash-lime);
  color: #10201e;
}
.task-list { gap: 7px; }
.task-list-item {
  display: grid;
  grid-template-columns: 22px minmax(120px, 1fr) auto minmax(96px, auto) minmax(90px, auto) 32px;
  gap: 12px;
  min-height: 62px;
  padding: 11px 14px;
  border-radius: 14px;
  box-shadow: none;
}
.task-list-item:hover { border-color: var(--dash-border-hover); }
.task-list-title { font-size: 12px; font-weight: 550; }
.task-list-item select.task-status-select {
  width: auto;
  min-width: 105px;
  min-height: 30px;
  padding: 0 28px 0 11px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 600;
}
.task-status-select.to-do { color: #60a5fa; }
.task-status-select.in-progress { color: #f59e0b; }
.task-status-select.completed { color: #34d399; }
.task-due-date { font-size: 10px; }
html[data-theme="light"] .task-summary-grid article,
html[data-theme="light"] .task-create-form { border-color: rgba(32, 67, 62, .13); background: #fff; }
html[data-theme="light"] .task-title-field input,
html[data-theme="light"] .task-create-details input,
