@media (max-width: 760px) {
  .tasks-page-heading { align-items: flex-start; flex-direction: column; }
  .tasks-date-pill { align-self: flex-start; }
  .task-create-details { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .task-create-details .module-primary-button { grid-column: 1 / -1; }
  .task-list-item { grid-template-columns: 22px minmax(0, 1fr) auto 32px; }
  .task-list-item .task-priority-tag { grid-column: 2; justify-self: start; }
  .task-list-item .task-due-date { grid-column: 3; grid-row: 2; }
  .task-list-item .task-status-select { grid-column: 2 / 4; grid-row: 3; justify-self: start; }
  .task-list-item .task-delete-button { grid-column: 4; grid-row: 1; }
}
@media (max-width: 560px) {
  .task-summary-grid { gap: 7px; }
  .task-summary-grid article { min-height: 58px; align-items: flex-start; flex-direction: column; padding: 10px; }
  .task-summary-grid article span { font-size: 9px; }
  .task-summary-grid article b { font-size: 18px; }
  .task-create-form { padding: 14px; }
  .task-create-details { grid-template-columns: 1fr 1fr; }
  .task-create-details > label:first-child { grid-column: 1 / -1; }
  .task-filter-tabs { width: 100%; justify-content: space-between; }
  .task-filter-tabs button { padding-inline: 9px; font-size: 10px; }
}
@media (max-width: 900px) {
  .task-create-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .task-create-form input:first-child { grid-column: 1 / -1; }
  .bento-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: auto; }
  .flash-card, .quiz-card, .mindmap-card, .planner-card { grid-column: auto; grid-row: auto; min-height: 280px; }
  .mindmap-card { grid-column: 1 / -1; }
}
@media (max-width: 560px) {
  .welcome-art-wrap { display: block; transform: scale(.82); transform-origin: center; margin-block: -18px -12px; }
  .welcome-copy h1 { font-size: 34px; line-height: 1.1; }
  .dashboard-eyebrow { justify-content: center; }
  .agenda-widget { padding: 16px; }
  .agenda-heading { align-items: flex-start; }
  .agenda-heading h2 { font-size: 16px; }
  .agenda-heading > button { white-space: nowrap; font-size: 9px; }
  .agenda-task { gap: 7px; }
  .agenda-task-title { font-size: 10px; }
  .task-priority-tag { padding: 3px 6px; font-size: 8px; }
  .agenda-deadline { min-width: 40px; font-size: 9px; }
  .notebooks-heading { align-items: flex-start; }
  .notebook-tools { justify-content: flex-start; }
  .task-create-form { grid-template-columns: 1fr; }
  .task-create-form input:first-child { grid-column: auto; }
  .task-list-item { flex-wrap: wrap; gap: 8px; }
  .task-list-title { flex: 1 1 calc(100% - 35px); }
  .task-list-item select { width: auto; flex: 1; }
  .task-due-date { min-width: auto; }
  .notebook-workspace-tabs { max-width: 100%; overflow-x: auto; }
  .notebook-workspace-tabs button { white-space: nowrap; padding-inline: 12px; }
}

