 type Notebook = {
   id: string;
   title: string;
   subtitle: string;
   content: string;
   notes: number;
   opened: string;
   createdAt?: string;
   symbol: string;
   accent: "teal" | "coral";
 };

 type StudyMessage = {
   id: string;
   role: "user" | "assistant";
   content: string;
 };

 type StudyTask = {
   id: string;
   title: string;
   status: "To Do" | "In Progress" | "Completed";
   priority: "High" | "Medium" | "Low";
   dueDate: string;
   createdAt: string;
 };

 function localDateKey(date = new Date()) {
   const year = date.getFullYear();
   const month = String(date.getMonth() + 1).padStart(2, "0");
   const day = String(date.getDate()).padStart(2, "0");
   return `${year}-${month}-${day}`;
 }

 type Flashcard = { front: string; back: string };
 type FlashcardDeck = {
   id: string;
   notebook_id: string;
   title: string;
   difficulty: "easy" | "medium" | "hard";
   cards: Flashcard[];
   created_at: string;
 };
 type QuizQuestion = {
