    }
    setNotice(result.warning ?? "Quiz graded. Synapse updated your notes with the concepts to revisit.");
  } catch (error) {
    setNotice(error instanceof Error ? error.message : "Could not submit this quiz.");
  } finally {
    setIsSubmittingQuiz(false);
  }
}

