}
.module-chat-panel { display: flex; min-height: min(660px, calc(100vh - 270px)); flex-direction: column; }
.module-chat-history { display: flex; flex: 1; flex-direction: column; gap: 14px; overflow: auto; padding: 24px; }
.module-chat-welcome { display: grid; justify-items: center; gap: 10px; max-width: 600px; margin: auto; text-align: center; }
.module-chat-welcome > b { font-size: 18px; }
.module-chat-welcome > p { max-width: 470px; margin: 0; color: #9eaaa8; font-size: 12px; line-height: 1.7; }
.module-chat-spark { display: grid; width: 48px; height: 48px; place-items: center; border: 1px solid rgba(99, 188, 174, 0.24); border-radius: 16px; background: rgba(99, 188, 174, 0.1); color: #76cabc; }
.chat-suggestions { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-top: 10px; }
.chat-suggestions button { padding: 9px 12px; border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 20px; background: transparent; color: inherit; font-size: 10px; cursor: pointer; }
.chat-suggestions button:hover { border-color: rgba(99, 188, 174, 0.45); background: rgba(99, 188, 174, 0.07); }
.module-chat-panel .study-chat-form { align-items: center; }
.module-chat-footnote { padding: 0 22px 14px; color: #808c89; font-size: 9px; text-align: center; }
.module-toolbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.025);
}
.module-toolbar > span { color: #919d9a; font-size: 10px; }
.module-generator-controls { flex-wrap: wrap; }
.module-generator-controls label { min-width: 120px; }
.module-generator-controls input { width: 100%; }
.module-primary-button, .module-secondary-button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 15px;
  border: 1px solid transparent;
  border-radius: 10px;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
}
.module-primary-button { background: #68c2b2; color: #071613; }
.module-primary-button:hover:not(:disabled) { transform: translateY(-1px); background: #83d3c5; }
.module-secondary-button { border-color: rgba(255, 255, 255, 0.12); background: rgba(255, 255, 255, 0.04); color: inherit; }
.module-secondary-button:hover:not(:disabled) { border-color: rgba(99, 188, 174, 0.4); }
.module-primary-button:disabled, .module-secondary-button:disabled { cursor: not-allowed; opacity: 0.48; }
.notes-editor-card { display: flex; min-height: 470px; flex-direction: column; }
.notes-title-input { padding: 19px 20px 14px; border: 0; border-bottom: 1px solid rgba(255, 255, 255, 0.08); outline: 0; background: transparent; color: inherit; font: inherit; font-size: 18px; font-weight: 700; }
.notes-editor { width: 100%; min-height: 350px; flex: 1; resize: vertical; padding: 18px 20px; border: 0; outline: 0; background: transparent; color: inherit; font: inherit; font-size: 13px; line-height: 1.8; }
.notes-editor-footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px; border-top: 1px solid rgba(255, 255, 255, 0.08); color: #8d9996; font-size: 10px; }
.notes-editor-footer > div { display: flex; gap: 8px; }
.module-empty-state { padding: 22px; border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 14px; color: #9baaa8; font-size: 12px; text-align: center; }
.flashcard-study-area { display: grid; justify-items: center; gap: 16px; padding: 24px; border: 1px solid rgba(99, 188, 174, 0.16); border-radius: 18px; background: radial-gradient(circle at 50% 0, rgba(99, 188, 174, 0.09), transparent 65%); }
.flashcard-face { display: grid; width: min(540px, 100%); min-height: 230px; justify-items: center; align-content: center; gap: 18px; padding: 24px; border: 1px solid rgba(255, 255, 255, 0.12); border-radius: 17px; background: rgba(255, 255, 255, 0.04); color: inherit; cursor: pointer; text-align: center; transition: transform 0.25s ease, border-color 0.25s ease; }
.flashcard-face:hover { transform: translateY(-3px); border-color: rgba(99, 188, 174, 0.4); }
.flashcard-face small { color: #70c6b7; font-size: 9px; font-weight: 700; letter-spacing: 0.13em; }
.flashcard-face span { max-width: 430px; font-size: 20px; line-height: 1.5; white-space: pre-wrap; }
.flashcard-face em { color: #8e9a97; font-size: 10px; font-style: normal; }
.flashcard-controls { display: flex; width: min(540px, 100%); align-items: center; justify-content: space-between; gap: 12px; }
.flashcard-controls b { overflow: hidden; color: #aebbb7; font-size: 10px; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }
.saved-study-sets { display: grid; gap: 12px; margin-top: 5px; }
.saved-study-sets > h2 { display: flex; align-items: center; gap: 9px; margin: 0; font-size: 15px; }
.saved-study-sets > h2 span { display: grid; min-width: 22px; height: 22px; place-items: center; border-radius: 50%; background: rgba(99, 188, 174, 0.12); color: #70c6b7; font-size: 10px; }

