      .eq("thread_id", threadId)
      .eq("user_id", user.id)
      .order("created_at", { ascending: true })
      .limit(100);

    return NextResponse.json({
      threadId,
      messages: messages ?? [],
    });
  } catch (error) {
    console.warn("Could not load study chat from database, using local session:", error);
